static void *probe_imu_raw_thread(void *arg)
{
  static const uint8_t registers[3] =
    {
      PROBE_IMU_CTRL1_XL, PROBE_IMU_CTRL2_G, PROBE_IMU_CTRL3_C
    };
  static const uint8_t configured[3] =
    {
      PROBE_IMU_CTRL1_XL_104HZ_4G,
      PROBE_IMU_CTRL2_G_104HZ_500DPS,
      PROBE_IMU_CTRL3_C_BDU_IF_INC
    };
  bool saved_valid[3] = {false, false, false};
  uint8_t saved[3] = {0, 0, 0};
  uint8_t sample[PROBE_IMU_RAW_SAMPLE_SIZE];
  struct timespec deadline;
  struct timespec wake;
  uint64_t previous_us;
  uint64_t period_sum_us = 0;
  uint64_t period_min_us = UINT64_MAX;
  uint64_t period_max_us = 0;
  uint32_t period_count = 0;
  uint32_t samples = 0;
  uint32_t i2c_errors = 0;
  uint32_t iteration;
  int32_t accel_mg[3];
  int32_t gyro_mdps[3];
  int16_t raw;
  int restore_status;
  int sleep_status;
  int fd;
  int ret;
  size_t i;

  (void)arg;
  fd = open(PROBE_IMU_I2C_DEV, O_RDONLY);
  if (fd < 0)
    {
      printf("openvela_ble_probe: IMU raw open %s failed errno=%d\n",
             PROBE_IMU_I2C_DEV, errno);
      return NULL;
    }

  for (i = 0; i < 3; i++)
    {
      ret = probe_imu_read(fd, PROBE_IMU_ADDR, registers[i], &saved[i], 1);
      if (ret != 0)
        {
          printf("openvela_ble_probe: IMU raw save reg=0x%02x failed"
                 " status=%d\n", registers[i], ret);
          goto restore;
        }

      saved_valid[i] = true;
    }

  for (i = 0; i < 3; i++)
    {
      uint8_t readback = 0;

      ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, registers[i],
                                configured[i]);
      if (ret == 0)
        {
          ret = probe_imu_read(fd, PROBE_IMU_ADDR, registers[i],
                               &readback, 1);
        }

      if (ret != 0 || readback != configured[i])
        {
          printf("openvela_ble_probe: IMU raw configure reg=0x%02x"
                 " status=%d readback=0x%02x expected=0x%02x\n",
                 registers[i], ret, readback, configured[i]);
          goto restore;
        }
    }

  printf("openvela_ble_probe: IMU raw config ctrl1_xl=0x48"
         " ctrl2_g=0x44 ctrl3_c=0x44\n");

  if (clock_gettime(CLOCK_MONOTONIC, &deadline) < 0)
    {
      printf("openvela_ble_probe: IMU raw clock_gettime failed errno=%d\n",
             errno);
      goto restore;
    }

  previous_us = probe_timespec_us(&deadline);
  for (iteration = 1;
       iteration <= PROBE_IMU_RAW_TEST_SECONDS * PROBE_IMU_RAW_TARGET_HZ;
       iteration++)
    {
      uint64_t wake_us;
      uint64_t period_us;

      probe_timespec_add_ns(&deadline, PROBE_IMU_RAW_PERIOD_NS);
      do
        {
          sleep_status = clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME,
                                         &deadline, NULL);
        }
      while (sleep_status == EINTR);

      if (sleep_status != 0 || clock_gettime(CLOCK_MONOTONIC, &wake) < 0)
        {
          printf("openvela_ble_probe: IMU raw timing failed status=%d\n",
                 sleep_status);
          break;
        }

      wake_us = probe_timespec_us(&wake);
      period_us = wake_us - previous_us;
      previous_us = wake_us;
      period_sum_us += period_us;
      period_count++;
      if (period_us < period_min_us)
        {
          period_min_us = period_us;
        }

      if (period_us > period_max_us)
        {
          period_max_us = period_us;
        }

      ret = probe_imu_read(fd, PROBE_IMU_ADDR, PROBE_IMU_OUTX_L_G,
                           sample, sizeof(sample));
      if (ret != 0)
        {
          i2c_errors++;
          continue;
        }

      for (i = 0; i < 3; i++)
        {
          raw = probe_imu_get_le16(&sample[i * 2]);
          gyro_mdps[i] = (int32_t)raw * 175 / 10;
          raw = probe_imu_get_le16(&sample[6 + i * 2]);
          accel_mg[i] = (int32_t)raw * 122 / 1000;
        }

      samples++;
      if (iteration % PROBE_IMU_RAW_TARGET_HZ == 0)
        {
          printf("openvela_ble_probe: IMU raw sample n=%lu"
                 " accel_mg=[%ld,%ld,%ld] gyro_mdps=[%ld,%ld,%ld]\n",
                 (unsigned long)samples,
                 (long)accel_mg[0], (long)accel_mg[1], (long)accel_mg[2],
                 (long)gyro_mdps[0], (long)gyro_mdps[1],
                 (long)gyro_mdps[2]);
        }
    }

  printf("openvela_ble_probe: IMU raw summary target_hz=104 samples=%lu"
         " i2c_errors=%lu period_us_min=%llu avg=%llu max=%llu\n",
         (unsigned long)samples, (unsigned long)i2c_errors,
         (unsigned long long)(period_count == 0 ? 0 : period_min_us),
         (unsigned long long)(period_count == 0 ? 0 :
                              period_sum_us / period_count),
         (unsigned long long)(period_count == 0 ? 0 : period_max_us));

restore:
  restore_status = probe_imu_restore_registers(fd, saved, saved_valid);
  printf("openvela_ble_probe: IMU raw registers restored status=%d\n",
         restore_status);
  close(fd);
  return NULL;
}

static int probe_monotonic_ms(uint64_t *now_ms)
{
  struct timespec now;

  if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
    {
      return -1;
    }

  *now_ms = (uint64_t)now.tv_sec * 1000u +
            (uint64_t)now.tv_nsec / 1000000u;
  return 0;
}

static uint32_t probe_get_le32(const uint8_t *value)
{
  return (uint32_t)value[0] |
         ((uint32_t)value[1] << 8) |
         ((uint32_t)value[2] << 16) |
         ((uint32_t)value[3] << 24);
}

