364	
365	int sifli_gpio_initialize(void)
366	{
367	  int i;
368	  int pincount = 0;
369	#if BOARD_NGPIOIN > 0
370	  for (i = 0; i < BOARD_NGPIOIN; i++)
371	    {
372	      /* Setup and register the GPIO pin */
373	
374	      g_gpin[i].gpio.gp_pintype = GPIO_INPUT_PIN;
375	      g_gpin[i].gpio.gp_ops     = &gpin_ops;
376	      g_gpin[i].id              = i;
377	      gpio_pin_register(&g_gpin[i].gpio, pincount);
378	
379	      /* Configure the pin that will be used as input */
380	
381	      sifli_gpio_config(g_gpioinputs[i], GPIO_INPUT);
382	
383	      pincount++;
384	    }
385	#endif
386	
387	#if BOARD_NGPIOOUT > 0
388	  for (i = 0; i < BOARD_NGPIOOUT; i++)
389	    {
390	      /* Setup and register the GPIO pin */
391	
392	      g_gpout[i].gpio.gp_pintype = GPIO_OUTPUT_PIN;
393	      g_gpout[i].gpio.gp_ops     = &gpout_ops;
394	      g_gpout[i].id              = i;
395	      gpio_pin_register(&g_gpout[i].gpio, pincount);
396	
397	      /* Configure the pin that will be used as output */
398	
399	      sifli_gpio_config(g_gpiooutputs[i], GPIO_OUTPUT);
400	      sifli_gpio_write(g_gpiooutputs[i], 0);
401	
402	      pincount++;
403	    }
404	#endif
405	
406	#if BOARD_NGPIOINT > 0
407	  for (i = 0; i < BOARD_NGPIOINT; i++)
408	    {
409	      /* Setup and register the GPIO pin */
410	
411	      g_gpint[i].sifli_gpio.gpio.gp_pintype = GPIO_INTERRUPT_BOTH_PIN;
412	      g_gpint[i].sifli_gpio.gpio.gp_ops     = &gpint_ops;
413	      g_gpint[i].sifli_gpio.id              = i;
414	      gpio_pin_register(&g_gpint[i].sifli_gpio.gpio, pincount);
415	
416	      /* Configure the pin that will be used as interrupt input */
417	
418	      sifli_gpio_config(g_gpiointinputs[i], GPIO_INPUT);
419	
420	      pincount++;
421	    }
422	#endif
423	
424	  return 0;
425	}
