 40	/****************************************************************************
 41	 * Name: sem_post
 42	 *
 43	 * Description:
 44	 *   When a task has finished with a semaphore, it will call sem_post().
 45	 *   This function unlocks the semaphore referenced by sem by performing the
 46	 *   semaphore unlock operation on that semaphore.
 47	 *
 48	 *   If the semaphore value resulting from this operation is positive, then
 49	 *   no tasks were blocked waiting for the semaphore to become unlocked; the
 50	 *   semaphore is simply incremented.
 51	 *
 52	 *   If the value of the semaphore resulting from this operation is zero,
 53	 *   then one of the tasks blocked waiting for the semaphore shall be
 54	 *   allowed to return successfully from its call to nxsem_wait().
 55	 *
 56	 * Input Parameters:
 57	 *   sem - Semaphore descriptor
 58	 *
 59	 * Returned Value:
 60	 *   This function is a standard, POSIX application interface.  It will
 61	 *   return zero (OK) if successful.  Otherwise, -1 (ERROR) is returned and
 62	 *   the errno value is set appropriately.
 63	 *
 64	 * Assumptions:
 65	 *   This function may be called from an interrupt handler.
 66	 *
 67	 ****************************************************************************/
 68	
 69	int sem_post(FAR sem_t *sem)
 70	{
 71	  int ret;
 72	
 73	  /* Make sure we were supplied with a valid semaphore. */
 74	
 75	  if (sem == NULL)
 76	    {
 77	      set_errno(EINVAL);
 78	      return ERROR;
 79	    }
 80	
 81	  ret = nxsem_post(sem);
 82	  if (ret < 0)
 83	    {
 84	      set_errno(-ret);
 85	      ret = ERROR;
 86	    }
 87	
 88	  return ret;
 89	}
