 188	static int gpio_isr(int irq, void *context, void *arg)
 189	{
 190	  if ((GPIO_TypeDef *)hwp_gpio1 == (GPIO_TypeDef *)arg)
 235	      GPIO_InitStruct.Pull = GPIO_PULLUP;
 236	      GPIO_InitStruct.Mode = GPIO_MODE_IT_FALLING;
 237	      break;
 238	    case GPIO_EVENT_MODE_RISING_FALLING:
 239	      GPIO_InitStruct.Pull = GPIO_NOPULL;
 240	      GPIO_InitStruct.Mode = GPIO_MODE_IT_RISING_FALLING;
 241	      break;
 242	    case GPIO_EVENT_MODE_HIGH_LEVEL:
 243	      GPIO_InitStruct.Pull = GPIO_NOPULL;
 244	      GPIO_InitStruct.Mode = GPIO_MODE_IT_HIGH_LEVEL;
 245	      break;
 246	    case GPIO_EVENT_MODE_LOW_LEVEL:
 247	      GPIO_InitStruct.Pull = GPIO_NOPULL;
 248	      GPIO_InitStruct.Mode = GPIO_MODE_IT_LOW_LEVEL;
 249	      break;
 250	    }
 251	
 252	    if (gphandle)
 253	    {
 254	      HAL_GPIO_Init(gphandle, &GPIO_InitStruct);
 255	
 256	      if (pin < GPIO1_PIN_NUM)   // PA
 257	      {
 258	#ifdef SOC_BF0_HCPU     // gpio1 only work on hcpu
 259	          irq_attach(GPIO1_IRQn + NVIC_IRQ_FIRST, gpio_isr, (void *)hwp_gpio1);
 260	          up_enable_irq(GPIO1_IRQn + NVIC_IRQ_FIRST);
 261	#endif // SOC_BF0_HCPU
 262	      }
 263	      else // PB
 264	      {
 265	          irq_attach(GPIO2_IRQn + NVIC_IRQ_FIRST, gpio_isr, (void *)hwp_gpio2);
 266	          up_enable_irq(GPIO2_IRQn + NVIC_IRQ_FIRST);          
 267	      }
 268	    }
 269	    else
 270	    {
 271	#ifdef hwp_pbr
 272	      pin_state = HAL_PBR_ReadPin(pin - PBR_PIN_OFFSET);
 273	      DEBUGASSERT(pin_state >= 0);
 274	
 275	      flags = enter_critical_section();
 276	      for (i = 0; i < pin_irq_hdr_num; i++)
 277	          if (pin_irq_hdr_tab[i].pin == pin)
 278	              break;
 279	      if (i < pin_irq_hdr_num)
 280	      {
 281	        pin_irq_hdr_tab[i].state = pin_state & 1;
 282	        pin_irq_hdr_tab[i].en = 1;
 283	      }
 284	      leave_critical_section(flags);
 285	#else
 286	      DEBUGASSERT(0);
 287	#endif /* hwp_pbr */
 288	    }
 289	}
 290	else
 291	{
 292	    if (gphandle)
 293	    {
 294	        HAL_GPIO_DeInit(gphandle, GPIO_InitStruct.Pin);
 295	    }
 296	    else
 297	    {
 298	#ifdef hwp_pbr
 299	      flags = enter_critical_section();
 300	      for (i = 0; i < pin_irq_hdr_num; i++)
 301	          if (pin_irq_hdr_tab[i].pin == pin)
 302	              break;
 303	      if (i < pin_irq_hdr_num)
 304	      {
 305	          pin_irq_hdr_tab[i].en = 0;
 306	      }
 307	    leave_critical_section(flags);
 308	#else
 309	        DEBUGASSERT(0);
 310	#endif /* hwp_pbr */
 311	    }
 312	    //pin_irq_enable_mask &= ~(1 << pin);
 313	    //HAL_NVIC_DisableIRQ(GPIO_IRQn);
 314	
 315	  }
 316	
 317	  return OK;
 318	}
