 332	static bool probe_detect_imu(void)
 333	{
 334	  static const uint8_t addresses[] = {0x6a, 0x6b};
 335	  uint8_t whoami;
 336	  bool detected = false;
 337	  int fd;
 338	  int ret;
 339	  size_t i;
 340	
 341	  fd = open(PROBE_IMU_I2C_DEV, O_RDONLY);
 342	  if (fd < 0)
 343	    {
 344	      printf("openvela_ble_probe: IMU probe open %s failed errno=%d\n",
 345	             PROBE_IMU_I2C_DEV, errno);
 346	      printf("openvela_ble_probe: IMU not detected at 0x6a or 0x6b\n");
 347	      return false;
 348	    }
 349	
 350	  for (i = 0; i < sizeof(addresses); i++)
 351	    {
 352	      whoami = 0;
 353	      ret = probe_imu_read(fd, addresses[i], PROBE_IMU_WHO_AM_I_REG,
 354	                           &whoami, 1);
 355	      printf("openvela_ble_probe: IMU probe addr=0x%02x transport=%d"
 356	             " whoami=0x%02x\n",
 357	             addresses[i], ret, whoami);
 358	      if (ret == 0 && whoami == PROBE_IMU_WHO_AM_I_VALUE)
 359	        {
 360	          printf("openvela_ble_probe: IMU detected addr=0x%02x"
 361	                 " whoami=0x6a\n", addresses[i]);
 362	          detected = true;
 363	        }
 364	    }
 365	
 366	  close(fd);
 367	  if (!detected)
 368	    {
 369	      printf("openvela_ble_probe: IMU not detected at 0x6a or 0x6b\n");
 370	    }
 371	
 372	  return detected;
 373	}
