 421	static void *probe_imu_raw_thread(void *arg)
 422	{
 423	  static const uint8_t registers[3] =
 424	    {
 425	      PROBE_IMU_CTRL1_XL, PROBE_IMU_CTRL2_G, PROBE_IMU_CTRL3_C
 426	    };
 427	  static const uint8_t configured[3] =
 428	    {
 429	      PROBE_IMU_CTRL1_XL_104HZ_4G,
 430	      PROBE_IMU_CTRL2_G_104HZ_500DPS,
 431	      PROBE_IMU_CTRL3_C_BDU_IF_INC
 432	    };
 433	  bool saved_valid[3] = {false, false, false};
 434	  uint8_t saved[3] = {0, 0, 0};
 435	  uint8_t sample[PROBE_IMU_RAW_SAMPLE_SIZE];
 436	  struct timespec deadline;
 437	  struct timespec wake;
 438	  uint64_t previous_us;
 439	  uint64_t period_sum_us = 0;
 440	  uint64_t period_min_us = UINT64_MAX;
 441	  uint64_t period_max_us = 0;
 442	  uint32_t period_count = 0;
 443	  uint32_t samples = 0;
 444	  uint32_t i2c_errors = 0;
 445	  uint32_t iteration;
 446	  int32_t accel_mg[3];
 447	  int32_t gyro_mdps[3];
 448	  int16_t raw;
 449	  int restore_status;
 450	  int sleep_status;
 451	  int fd;
 452	  int ret;
 453	  size_t i;
 454	
 455	  (void)arg;
 456	  printf("openvela_ble_probe: IMU raw thread entered\n");
 457	  fd = open(PROBE_IMU_I2C_DEV, O_RDONLY);
 458	  if (fd < 0)
 459	    {
 460	      printf("openvela_ble_probe: IMU raw open %s failed errno=%d\n",
 461	             PROBE_IMU_I2C_DEV, errno);
 462	      return NULL;
 463	    }
 464	
 465	  for (i = 0; i < 3; i++)
 466	    {
 467	      ret = probe_imu_read(fd, PROBE_IMU_ADDR, registers[i], &saved[i], 1);
 468	      if (ret != 0)
 469	        {
 470	          printf("openvela_ble_probe: IMU raw save reg=0x%02x failed"
 471	                 " status=%d\n", registers[i], ret);
 472	          goto restore;
 473	        }
 474	
 475	      saved_valid[i] = true;
 476	    }
 477	
 478	  for (i = 0; i < 3; i++)
 479	    {
 480	      uint8_t readback = 0;
 481	
 482	      ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, registers[i],
 483	                                configured[i]);
 484	      if (ret == 0)
 485	        {
 486	          ret = probe_imu_read(fd, PROBE_IMU_ADDR, registers[i],
 487	                               &readback, 1);
 488	        }
 489	
 490	      if (ret != 0 || readback != configured[i])
 491	        {
 492	          printf("openvela_ble_probe: IMU raw configure reg=0x%02x"
 493	                 " status=%d readback=0x%02x expected=0x%02x\n",
 494	                 registers[i], ret, readback, configured[i]);
 495	          goto restore;
 496	        }
 497	    }
 498	
 499	  printf("openvela_ble_probe: IMU raw config ctrl1_xl=0x48"
 500	         " ctrl2_g=0x44 ctrl3_c=0x44\n");
 501	
 502	  if (clock_gettime(CLOCK_MONOTONIC, &deadline) < 0)
 503	    {
 504	      printf("openvela_ble_probe: IMU raw clock_gettime failed errno=%d\n",
 505	             errno);
 506	      goto restore;
 507	    }
 508	
 509	  previous_us = probe_timespec_us(&deadline);
 510	  for (iteration = 1;
 511	       iteration <= PROBE_IMU_RAW_TEST_SECONDS * PROBE_IMU_RAW_TARGET_HZ;
 512	       iteration++)
 513	    {
 514	      uint64_t wake_us;
 515	      uint64_t period_us;
 516	
 517	      probe_timespec_add_ns(&deadline, PROBE_IMU_RAW_PERIOD_NS);
 518	      do
 519	        {
 520	          sleep_status = clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME,
 521	                                         &deadline, NULL);
 522	        }
 523	      while (sleep_status == EINTR);
 524	
 525	      if (sleep_status != 0 || clock_gettime(CLOCK_MONOTONIC, &wake) < 0)
 526	        {
 527	          printf("openvela_ble_probe: IMU raw timing failed status=%d\n",
 528	                 sleep_status);
 529	          break;
 530	        }
 531	
 532	      wake_us = probe_timespec_us(&wake);
 533	      period_us = wake_us - previous_us;
 534	      previous_us = wake_us;
 535	      period_sum_us += period_us;
 536	      period_count++;
 537	      if (period_us < period_min_us)
 538	        {
 539	          period_min_us = period_us;
 540	        }
 541	
 542	      if (period_us > period_max_us)
 543	        {
 544	          period_max_us = period_us;
 545	        }
 546	
 547	      ret = probe_imu_read(fd, PROBE_IMU_ADDR, PROBE_IMU_OUTX_L_G,
 548	                           sample, sizeof(sample));
 549	      if (ret != 0)
 550	        {
 551	          i2c_errors++;
 552	          continue;
 553	        }
 554	
 555	      for (i = 0; i < 3; i++)
 556	        {
 557	          raw = probe_imu_get_le16(&sample[i * 2]);
 558	          gyro_mdps[i] = (int32_t)raw * 175 / 10;
 559	          raw = probe_imu_get_le16(&sample[6 + i * 2]);
 560	          accel_mg[i] = (int32_t)raw * 122 / 1000;
 561	        }
 562	
 563	      samples++;
 564	      if (iteration % PROBE_IMU_RAW_TARGET_HZ == 0)
 565	        {
 566	          printf("openvela_ble_probe: IMU raw sample n=%lu"
 567	                 " accel_mg=[%ld,%ld,%ld] gyro_mdps=[%ld,%ld,%ld]\n",
 568	                 (unsigned long)samples,
 569	                 (long)accel_mg[0], (long)accel_mg[1], (long)accel_mg[2],
 570	                 (long)gyro_mdps[0], (long)gyro_mdps[1],
 571	                 (long)gyro_mdps[2]);
 572	        }
 573	    }
 574	
 575	  printf("openvela_ble_probe: IMU raw summary target_hz=104 samples=%lu"
 576	         " i2c_errors=%lu period_us_min=%llu avg=%llu max=%llu\n",
 577	         (unsigned long)samples, (unsigned long)i2c_errors,
 578	         (unsigned long long)(period_count == 0 ? 0 : period_min_us),
 579	         (unsigned long long)(period_count == 0 ? 0 :
 580	                              period_sum_us / period_count),
 581	         (unsigned long long)(period_count == 0 ? 0 : period_max_us));
 582	
 583	restore:
 584	  restore_status = probe_imu_restore_registers(fd, saved, saved_valid);
 585	  printf("openvela_ble_probe: IMU raw registers restored status=%d\n",
 586	         restore_status);
 587	  close(fd);
 588	  return NULL;
 589	}
