 298	static int probe_imu_read(int fd, uint8_t addr, uint8_t reg,
 299	                          uint8_t *value, size_t length)
 300	{
 301	  struct i2c_msg_s messages[2];
 302	
 303	  messages[0].frequency = PROBE_IMU_I2C_FREQUENCY;
 304	  messages[0].addr = addr;
 305	  messages[0].flags = I2C_M_NOSTOP;
 306	  messages[0].buffer = &reg;
 307	  messages[0].length = 1;
 308	  messages[1].frequency = PROBE_IMU_I2C_FREQUENCY;
 309	  messages[1].addr = addr;
 310	  messages[1].flags = I2C_M_READ | I2C_M_NOSTART;
 311	  messages[1].buffer = value;
 312	  messages[1].length = length;
 313	
 314	  return probe_imu_transfer(fd, messages, 2);
 315	}
