 386	static void probe_timespec_add_ns(struct timespec *time, uint64_t ns)
 387	{
 388	  uint64_t nsec = (uint64_t)time->tv_nsec + ns;
 389	
 390	  time->tv_sec += (time_t)(nsec / 1000000000ULL);
 391	  time->tv_nsec = (long)(nsec % 1000000000ULL);
 392	}
