 594	  bool launch;
 595	  int detach_ret;
 596	  int ret;
 597	
 598	  pthread_mutex_lock(&g_state_lock);
 599	  launch = g_imu_raw_launch_pending && !g_imu_raw_launch_attempted;
 600	  if (launch)
 601	    {
 602	      g_imu_raw_launch_pending = false;
 603	      g_imu_raw_launch_attempted = true;
 604	    }
 605	  pthread_mutex_unlock(&g_state_lock);
 606	
 607	  if (!launch)
 608	    {
 609	      return;
 610	    }
 611	
 612	  ret = pthread_create(&thread, NULL, probe_imu_raw_thread, NULL);
 613	  printf("openvela_ble_probe: IMU raw pthread create ret=%d\n", ret);
 614	  if (ret != 0)
 615	    {
 616	      return;
 617	    }
 618	
 619	  pthread_mutex_lock(&g_state_lock);
 620	  g_imu_raw_started = true;
 621	  pthread_mutex_unlock(&g_state_lock);
 622	
 623	  detach_ret = pthread_detach(thread);
 624	  printf("openvela_ble_probe: IMU raw pthread detach ret=%d\n", detach_ret);
 625	}
