 110	static void pin_irq_hdr(GPIO_TypeDef *hgpio, int pin)
 111	{
 112	    int i;
 113	
 114	    if (hgpio == (GPIO_TypeDef *)hwp_gpio1)
 115	    {
 116	      // Do nothing
 117	    }
 118	    else if (hgpio == (GPIO_TypeDef *)hwp_gpio2)
 119	      pin += GPIO1_PIN_NUM;
 120	#ifdef hwp_pbr
 121	    else if (hgpio == (GPIO_TypeDef *)hwp_pbr)
 122	      pin = pin + GPIO1_PIN_NUM + GPIO2_PIN_NUM;
 123	#endif /* hwp_pbr */
 124	    else
 125	      DEBUGASSERT(0);
 126	
 127	    for (i = 0; i < pin_irq_hdr_num; i++)
 128	      if (pin_irq_hdr_tab[i].pin == pin)
 129	          break;
 130	
 131	    if (i < pin_irq_hdr_num)
 132	    {
 133	#ifdef hwp_pbr
 134	      if (hgpio == (GPIO_TypeDef *)hwp_pbr)
 135	      {
 136	        int8_t val = HAL_PBR_ReadPin(pin);
 137	        DEBUGASSERT(val >= 0);
 138	        pin_irq_hdr_tab[i].state = val;
 139	      }
 140	#endif /* hwp_pbr */
 141	      pin_irq_hdr_tab[i].func(pin_irq_hdr_tab[i].args);
 142	    }
 143	}
