 150	static void GPIO2_IRQHandler(void)
 151	{
 152	    uint32_t i;
 153	    uint32_t pin;
 154	
 155	#ifdef SOC_BF0_HCPU
 156	    for (i = 0; i < pin_irq_hdr_num; i++)
 157	    {
 158	        /* LPSYS should be active when HPSYS is active,
 159	           so HCPU only needs to handle interrupt source registered by its own */
 160	        if ((pin_irq_hdr_tab[i].pin >= GPIO1_PIN_NUM) && (pin_irq_hdr_tab[i].pin < PBR_PIN_OFFSET))
 161	        {
 162	            pin = pin_irq_hdr_tab[i].pin - GPIO1_PIN_NUM;
 163	            HAL_GPIO_EXTI_IRQHandler((GPIO_TypeDef *)hwp_gpio2, pin);
 164	        }
 165	    }
 166	#else
 167	    if (HAL_LPAON_IS_HP_ACTIVE())
 168	    {
 169	        /* If HPSYS is active, only handle interrupt source registered by LCPU,
 170	           others should be handled by HCPU */
 171	        for (i = 0; i < pin_irq_hdr_num; i++)
 172	        {
 173	            if ((pin_irq_hdr_tab[i].pin >= GPIO1_PIN_NUM) && (pin_irq_hdr_tab[i].pin < PBR_PIN_OFFSET))
 174	            {
 175	                pin = pin_irq_hdr_tab[i].pin - GPIO1_PIN_NUM;
 176	                HAL_GPIO_EXTI_IRQHandler((GPIO_TypeDef *)hwp_gpio2, pin);
 177	            }
 178	        }
 179	    }
 180	    else
 181	    {
 182	        /* If HPSYS is inactive, clear all interrupt source even if it's not registered by LCPU side */
 183	        HAL_GPIO_IRQHandler((GPIO_TypeDef *)hwp_gpio2);
 184	    }
 185	#endif /* SOC_BF0_HCPU */
 186	}
