 317	static int probe_imu_write_reg(int fd, uint8_t addr, uint8_t reg,
 318	                               uint8_t value)
 319	{
 320	  struct i2c_msg_s message;
 321	  uint8_t data[2] = {reg, value};
 322	
 323	  message.frequency = PROBE_IMU_I2C_FREQUENCY;
 324	  message.addr = addr;
 325	  message.flags = 0;
 326	  message.buffer = data;
 327	  message.length = sizeof(data);
 328	
 329	  return probe_imu_transfer(fd, &message, 1);
 330	}
