 133	#ifdef hwp_pbr
 134	      if (hgpio == (GPIO_TypeDef *)hwp_pbr)
 135	      {
 136	        int8_t val = HAL_PBR_ReadPin(pin);
 137	        DEBUGASSERT(val >= 0);
 138	        pin_irq_hdr_tab[i].state = val;
 139	      }
 140	#endif /* hwp_pbr */
 141	      pin_irq_hdr_tab[i].func(pin_irq_hdr_tab[i].args);
 142	    }
