    83	
    84	void BSP_Power_Up(bool is_deep_sleep)
    85	{
    86	    BSP_PowerUpCustom(is_deep_sleep);
    87	#ifdef SOC_BF0_HCPU
    88	    if (!is_deep_sleep)
    89	    {
    90	#ifdef BSP_USING_NOR_FLASH2
    91	        FLASH_HandleTypeDef *flash_handle = sf32lb_flash_get_handle();
    92	        if (flash_handle)
    93	        {
    94	            HAL_FLASH_RELEASE_DPD(flash_handle);
