                            PROBE_IMU_CTRL3_C_BDU_IF_INC);
  if (ret == 0)
    {
      ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL1_XL,
                                PROBE_IMU_CTRL1_XL_104HZ_4G);
    }

  if (ret == 0)
    {
      ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL2_G,
                                PROBE_IMU_CTRL2_G_104HZ_500DPS);
    }

  if (ret == 0)
    {
      ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                PROBE_IMU_DRDY_PULSE_CFG_G,
                                saved[0] & ~0x80);
    }

  if (ret != 0)
    {
      printf("openvela_ble_probe: IMU DRDY configure failed status=%d\n",
             ret);
      goto restore;
    }

  if (sem_init(&g_imu_drdy_sem, 0, 0) < 0)
    {
      printf("openvela_ble_probe: IMU DRDY semaphore init failed errno=%d\n",
             errno);
      goto restore;
    }

  __atomic_store_n(&g_imu_drdy_irq_count, 0, __ATOMIC_RELAXED);
  ret = board_imu_int1_enable(probe_imu_int1_isr, NULL);
  if (ret != 0)
    {
      printf("openvela_ble_probe: IMU DRDY IRQ enable failed status=%d\n",
             ret);
      sem_destroy(&g_imu_drdy_sem);
      goto restore;
    }

  irq_enabled = true;

  /* Enable only accelerometer data-ready after the host IRQ is ready. */

  ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, PROBE_IMU_INT1_CTRL,
                            0x01);
  if (ret != 0)
    {
      printf("openvela_ble_probe: IMU DRDY route failed status=%d\n", ret);
      goto stop_irq;
    }

  int1_routed = true;

  printf("openvela_ble_probe: IMU DRDY config ctrl1_xl=0x48"
         " ctrl2_g=0x44 ctrl3_c=0x44 int1_ctrl=0x01 latched=1\n");

  if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0)
    {
      printf("openvela_ble_probe: IMU DRDY clock_gettime failed errno=%d\n",
             errno);
      goto stop_irq;
    }

  end_time = start_time;
  probe_timespec_add_ms(&end_time, PROBE_IMU_RAW_TEST_SECONDS * 1000);
  start_us = probe_timespec_us(&start_time);
  end_us = probe_timespec_us(&end_time);
  next_log_us = start_us + 1000000ULL;

  for (;;)
    {
      uint64_t now_us;
      uint64_t read_us;
      uint64_t period_us;

      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
        {
          printf("openvela_ble_probe: IMU DRDY clock read failed errno=%d\n",
                 errno);
          break;
        }

      now_us = probe_timespec_us(&now);
      if (now_us >= end_us)
        {
          break;
        }

      wait_until = now;
      probe_timespec_add_ms(&wait_until, PROBE_IMU_DRDY_WAIT_MS);
      if (probe_timespec_us(&wait_until) > end_us)
        {
          wait_until = end_time;
        }

      do
        {
          wait_status = sem_clockwait(&g_imu_drdy_sem, CLOCK_MONOTONIC,
                                      &wait_until);
        }
      while (wait_status < 0 && errno == EINTR);

      if (wait_status < 0)
        {
          if (errno == ETIMEDOUT)
            {
              timeouts++;
              continue;
            }

          printf("openvela_ble_probe: IMU DRDY semaphore wait failed"
                 " errno=%d\n", errno);
          break;
        }

      sem_wake_count++;

      ret = probe_imu_read(fd, PROBE_IMU_ADDR, PROBE_IMU_OUTX_L_G,
                           sample, sizeof(sample));
      if (ret != 0)
        {
          i2c_errors++;
          continue;
        }

      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
        {
          printf("openvela_ble_probe: IMU DRDY read timestamp failed"
                 " errno=%d\n", errno);
          break;
        }

      read_us = probe_timespec_us(&now);
      if (previous_read_us != 0)
        {
          period_us = read_us - previous_read_us;
          read_period_sum_us += period_us;
          read_period_count++;
          if (period_us < read_period_min_us)
            {
              read_period_min_us = period_us;
            }

          if (period_us > read_period_max_us)
            {
              read_period_max_us = period_us;
            }
        }

      previous_read_us = read_us;

      for (i = 0; i < 3; i++)
        {
          raw = probe_imu_get_le16(&sample[i * 2]);
          gyro_mdps[i] = (int32_t)raw * 175 / 10;
          raw = probe_imu_get_le16(&sample[6 + i * 2]);
          accel_mg[i] = (int32_t)raw * 122 / 1000;
        }

      read_ok++;
      if (read_us >= next_log_us)
        {
          printf("openvela_ble_probe: IMU DRDY sample n=%lu"
                 " accel_mg=[%ld,%ld,%ld] gyro_mdps=[%ld,%ld,%ld]\n",
                 (unsigned long)read_ok,
                 (long)accel_mg[0], (long)accel_mg[1], (long)accel_mg[2],
                 (long)gyro_mdps[0], (long)gyro_mdps[1],
                 (long)gyro_mdps[2]);
          next_log_us += 1000000ULL;
        }
    }

stop_irq:
  if (irq_enabled)
    {
      cleanup_ret = board_imu_int1_disable();
      if (cleanup_ret != 0 && restore_status == 0)
        {
          restore_status = cleanup_ret;
        }
      irq_enabled = false;
    }

  if (int1_routed)
    {
      cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                        PROBE_IMU_INT1_CTRL, 0x00);
      if (cleanup_ret != 0 && restore_status == 0)
        {
          restore_status = cleanup_ret;
        }
    }

  sem_destroy(&g_imu_drdy_sem);

restore:
  /* Restore controls first, then the original interrupt routing and mode. */

  for (i = 2; i < 5; i++)
    {
      if (saved_valid[i])
        {
          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                            registers[i], saved[i]);
          if (cleanup_ret != 0 && restore_status == 0)
            {
              restore_status = cleanup_ret;
            }
        }
    }

  for (i = 1; i < 2; i++)
    {
      if (saved_valid[i])
        {
          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                            registers[i], saved[i]);
          if (cleanup_ret != 0 && restore_status == 0)
            {
              restore_status = cleanup_ret;
            }
        }
    }

  if (saved_valid[0])
    {
      cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, registers[0],
                                        saved[0]);
      if (cleanup_ret != 0 && restore_status == 0)
        {
          restore_status = cleanup_ret;
        }
    }

  irq_count = __atomic_load_n(&g_imu_drdy_irq_count, __ATOMIC_RELAXED);
  if (start_us != 0 && clock_gettime(CLOCK_MONOTONIC, &now) == 0)
    {
      end_us = probe_timespec_us(&now);
    }

  printf("openvela_ble_probe: IMU DRDY summary duration_ms=%llu"
         " irq_count=%lu sem_wake_count=%lu read_ok=%lu i2c_errors=%lu"
         " timeouts=%lu irq_minus_wake=%ld wake_minus_read_ok=%ld"
         " read_period_us_min=%llu avg=%llu max=%llu\n",
         (unsigned long long)(start_us == 0 ? 0 : (end_us - start_us) / 1000),
         (unsigned long)irq_count, (unsigned long)sem_wake_count,
         (unsigned long)read_ok, (unsigned long)i2c_errors,
         (unsigned long)timeouts,
         (long)((int64_t)irq_count - sem_wake_count),
         (long)((int64_t)sem_wake_count - read_ok),
         (unsigned long long)(read_period_count == 0 ? 0 :
                              read_period_min_us),
         (unsigned long long)(read_period_count == 0 ? 0 :
                              read_period_sum_us / read_period_count),
         (unsigned long long)(read_period_count == 0 ? 0 :
                              read_period_max_us));
  printf("openvela_ble_probe: IMU DRDY registers restored status=%d\n",
         restore_status);
  close(fd);
  return NULL;
}

