  messages[0].frequency = PROBE_IMU_I2C_FREQUENCY;
  messages[0].addr = addr;
  messages[0].flags = I2C_M_NOSTOP;
  messages[0].buffer = &reg;
  messages[0].length = 1;
  messages[1].frequency = PROBE_IMU_I2C_FREQUENCY;
  messages[1].addr = addr;
  messages[1].flags = I2C_M_READ | I2C_M_NOSTART;
  messages[1].buffer = value;
  messages[1].length = length;

  return probe_imu_transfer(fd, messages, 2);
}

static int probe_imu_write_reg(int fd, uint8_t addr, uint8_t reg,
                               uint8_t value)
{
  struct i2c_msg_s message;
  uint8_t data[2] = {reg, value};

  message.frequency = PROBE_IMU_I2C_FREQUENCY;
  message.addr = addr;
  message.flags = 0;
  message.buffer = data;
  message.length = sizeof(data);

  return probe_imu_transfer(fd, &message, 1);
}

static bool probe_detect_imu(void)
{
  static const uint8_t addresses[] = {0x6a, 0x6b};
  uint8_t whoami;
  bool detected = false;
  int fd;
  int ret;
  size_t i;

  fd = open(PROBE_IMU_I2C_DEV, O_RDONLY);
  if (fd < 0)
    {
      printf("openvela_ble_probe: IMU probe open %s failed errno=%d\n",
             PROBE_IMU_I2C_DEV, errno);
      printf("openvela_ble_probe: IMU not detected at 0x6a or 0x6b\n");
      return false;
    }

  for (i = 0; i < sizeof(addresses); i++)
    {
      whoami = 0;
      ret = probe_imu_read(fd, addresses[i], PROBE_IMU_WHO_AM_I_REG,
                           &whoami, 1);
      printf("openvela_ble_probe: IMU probe addr=0x%02x transport=%d"
             " whoami=0x%02x\n",
             addresses[i], ret, whoami);
      if (ret == 0 && whoami == PROBE_IMU_WHO_AM_I_VALUE)
        {
          printf("openvela_ble_probe: IMU detected addr=0x%02x"
                 " whoami=0x6a\n", addresses[i]);
          detected = true;
        }
    }

  close(fd);
  if (!detected)
    {
      printf("openvela_ble_probe: IMU not detected at 0x6a or 0x6b\n");
    }

  return detected;
}

static int16_t probe_imu_get_le16(const uint8_t *data)
{
  return (int16_t)((uint16_t)data[0] | ((uint16_t)data[1] << 8));
}

static uint64_t probe_timespec_us(const struct timespec *time)
{
  return (uint64_t)time->tv_sec * 1000000ULL +
         (uint64_t)time->tv_nsec / 1000ULL;
}

static void probe_timespec_add_ms(struct timespec *time, uint32_t ms)
{
  uint64_t nsec = (uint64_t)time->tv_nsec +
                  (uint64_t)ms * 1000000ULL;

  time->tv_sec += (time_t)(nsec / 1000000000ULL);
  time->tv_nsec = (long)(nsec % 1000000000ULL);
}

static void probe_imu_int1_isr(void *arg)
{
  (void)arg;
  __atomic_add_fetch(&g_imu_drdy_irq_count, 1, __ATOMIC_RELAXED);
  sem_post(&g_imu_drdy_sem);
}

static void *probe_imu_raw_thread(void *arg)
{
  static const uint8_t registers[5] =
    {
      PROBE_IMU_DRDY_PULSE_CFG_G,
      PROBE_IMU_INT1_CTRL,
      PROBE_IMU_CTRL1_XL,
      PROBE_IMU_CTRL2_G,
      PROBE_IMU_CTRL3_C
    };
  bool saved_valid[5] = {false, false, false, false, false};
  uint8_t saved[5] = {0, 0, 0, 0, 0};
  uint8_t sample[PROBE_IMU_RAW_SAMPLE_SIZE];
  struct timespec start_time;
  struct timespec end_time;
  struct timespec wait_until;
  struct timespec now;
  uint64_t start_us;
  uint64_t end_us;
  uint64_t previous_read_us = 0;
  uint64_t read_period_sum_us = 0;
  uint64_t read_period_min_us = UINT64_MAX;
  uint64_t read_period_max_us = 0;
  uint64_t next_log_us;
  uint32_t read_period_count = 0;
  uint32_t sem_wake_count = 0;
  uint32_t read_ok = 0;
  uint32_t i2c_errors = 0;
  uint32_t timeouts = 0;
  uint32_t irq_count;
  int32_t accel_mg[3];
  int32_t gyro_mdps[3];
  int16_t raw;
  bool irq_enabled = false;
  bool int1_routed = false;
  int restore_status = 0;
  int cleanup_ret;
  int wait_status;
  int fd;
  int ret;
  size_t i;

  (void)arg;
  printf("openvela_ble_probe: IMU raw thread entered\n");
  fd = open(PROBE_IMU_I2C_DEV, O_RDONLY);
  if (fd < 0)
    {
      printf("openvela_ble_probe: IMU raw open %s failed errno=%d\n",
             PROBE_IMU_I2C_DEV, errno);
      return NULL;
    }

  for (i = 0; i < 5; i++)
    {
      ret = probe_imu_read(fd, PROBE_IMU_ADDR, registers[i], &saved[i], 1);
      if (ret != 0)
        {
          printf("openvela_ble_probe: IMU raw save reg=0x%02x failed"
                 " status=%d\n", registers[i], ret);
          goto restore;
        }

      saved_valid[i] = true;
    }

  ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL3_C,
                            PROBE_IMU_CTRL3_C_BDU_IF_INC);
  if (ret == 0)
    {
      ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL1_XL,
                                PROBE_IMU_CTRL1_XL_104HZ_4G);
    }

  if (ret == 0)
    {
      ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL2_G,
                                PROBE_IMU_CTRL2_G_104HZ_500DPS);
    }

  if (ret == 0)
    {
      ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                PROBE_IMU_DRDY_PULSE_CFG_G,
                                saved[0] & ~0x80);
    }

  if (ret != 0)
    {
      printf("openvela_ble_probe: IMU DRDY configure failed status=%d\n",
             ret);
      goto restore;
    }

  if (sem_init(&g_imu_drdy_sem, 0, 0) < 0)
    {
      printf("openvela_ble_probe: IMU DRDY semaphore init failed errno=%d\n",
             errno);
      goto restore;
    }

  __atomic_store_n(&g_imu_drdy_irq_count, 0, __ATOMIC_RELAXED);
  ret = board_imu_int1_enable(probe_imu_int1_isr, NULL);
  if (ret != 0)
    {
      printf("openvela_ble_probe: IMU DRDY IRQ enable failed status=%d\n",
             ret);
      sem_destroy(&g_imu_drdy_sem);
      goto restore;
    }

  irq_enabled = true;

  /* Enable only accelerometer data-ready after the host IRQ is ready. */

  ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, PROBE_IMU_INT1_CTRL,
                            0x01);
  if (ret != 0)
    {
      printf("openvela_ble_probe: IMU DRDY route failed status=%d\n", ret);
      goto stop_irq;
    }

  int1_routed = true;

  printf("openvela_ble_probe: IMU DRDY config ctrl1_xl=0x48"
         " ctrl2_g=0x44 ctrl3_c=0x44 int1_ctrl=0x01 latched=1\n");

  if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0)
    {
      printf("openvela_ble_probe: IMU DRDY clock_gettime failed errno=%d\n",
             errno);
      goto stop_irq;
    }

  end_time = start_time;
  probe_timespec_add_ms(&end_time, PROBE_IMU_RAW_TEST_SECONDS * 1000);
  start_us = probe_timespec_us(&start_time);
  end_us = probe_timespec_us(&end_time);
  next_log_us = start_us + 1000000ULL;

  for (;;)
    {
      uint64_t now_us;
      uint64_t read_us;
      uint64_t period_us;

      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
        {
          printf("openvela_ble_probe: IMU DRDY clock read failed errno=%d\n",
                 errno);
          break;
        }

      now_us = probe_timespec_us(&now);
      if (now_us >= end_us)
        {
          break;
        }

      wait_until = now;
      probe_timespec_add_ms(&wait_until, PROBE_IMU_DRDY_WAIT_MS);
      if (probe_timespec_us(&wait_until) > end_us)
        {
          wait_until = end_time;
        }

      do
        {
          wait_status = sem_clockwait(&g_imu_drdy_sem, CLOCK_MONOTONIC,
                                      &wait_until);
        }
      while (wait_status < 0 && errno == EINTR);

      if (wait_status < 0)
        {
          if (errno == ETIMEDOUT)
            {
              timeouts++;
              continue;
            }

          printf("openvela_ble_probe: IMU DRDY semaphore wait failed"
                 " errno=%d\n", errno);
          break;
        }

      sem_wake_count++;

      ret = probe_imu_read(fd, PROBE_IMU_ADDR, PROBE_IMU_OUTX_L_G,
                           sample, sizeof(sample));
      if (ret != 0)
        {
          i2c_errors++;
          continue;
        }

      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
        {
          printf("openvela_ble_probe: IMU DRDY read timestamp failed"
                 " errno=%d\n", errno);
          break;
        }

      read_us = probe_timespec_us(&now);
      if (previous_read_us != 0)
        {
          period_us = read_us - previous_read_us;
          read_period_sum_us += period_us;
          read_period_count++;
          if (period_us < read_period_min_us)
            {
              read_period_min_us = period_us;
            }

          if (period_us > read_period_max_us)
            {
              read_period_max_us = period_us;
            }
        }

      previous_read_us = read_us;

      for (i = 0; i < 3; i++)
        {
          raw = probe_imu_get_le16(&sample[i * 2]);
          gyro_mdps[i] = (int32_t)raw * 175 / 10;
          raw = probe_imu_get_le16(&sample[6 + i * 2]);
          accel_mg[i] = (int32_t)raw * 122 / 1000;
        }

      read_ok++;
      if (read_us >= next_log_us)
        {
          printf("openvela_ble_probe: IMU DRDY sample n=%lu"
                 " accel_mg=[%ld,%ld,%ld] gyro_mdps=[%ld,%ld,%ld]\n",
                 (unsigned long)read_ok,
                 (long)accel_mg[0], (long)accel_mg[1], (long)accel_mg[2],
                 (long)gyro_mdps[0], (long)gyro_mdps[1],
                 (long)gyro_mdps[2]);
          next_log_us += 1000000ULL;
        }
    }

stop_irq:
  if (irq_enabled)
    {
      cleanup_ret = board_imu_int1_disable();
      if (cleanup_ret != 0 && restore_status == 0)
        {
          restore_status = cleanup_ret;
        }
      irq_enabled = false;
    }

  if (int1_routed)
    {
      cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                        PROBE_IMU_INT1_CTRL, 0x00);
      if (cleanup_ret != 0 && restore_status == 0)
        {
          restore_status = cleanup_ret;
        }
    }

  sem_destroy(&g_imu_drdy_sem);

restore:
  /* Restore controls first, then the original interrupt routing and mode. */

  for (i = 2; i < 5; i++)
    {
      if (saved_valid[i])
        {
          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                            registers[i], saved[i]);
          if (cleanup_ret != 0 && restore_status == 0)
            {
              restore_status = cleanup_ret;
            }
        }
    }

  for (i = 1; i < 2; i++)
    {
      if (saved_valid[i])
        {
          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                            registers[i], saved[i]);
          if (cleanup_ret != 0 && restore_status == 0)
            {
              restore_status = cleanup_ret;
            }
        }
    }

  if (saved_valid[0])
    {
      cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, registers[0],
                                        saved[0]);
      if (cleanup_ret != 0 && restore_status == 0)
        {
          restore_status = cleanup_ret;
        }
    }

  irq_count = __atomic_load_n(&g_imu_drdy_irq_count, __ATOMIC_RELAXED);
  if (start_us != 0 && clock_gettime(CLOCK_MONOTONIC, &now) == 0)
    {
      end_us = probe_timespec_us(&now);
    }

  printf("openvela_ble_probe: IMU DRDY summary duration_ms=%llu"
         " irq_count=%lu sem_wake_count=%lu read_ok=%lu i2c_errors=%lu"
         " timeouts=%lu irq_minus_wake=%ld wake_minus_read_ok=%ld"
         " read_period_us_min=%llu avg=%llu max=%llu\n",
         (unsigned long long)(start_us == 0 ? 0 : (end_us - start_us) / 1000),
         (unsigned long)irq_count, (unsigned long)sem_wake_count,
         (unsigned long)read_ok, (unsigned long)i2c_errors,
         (unsigned long)timeouts,
         (long)((int64_t)irq_count - sem_wake_count),
         (long)((int64_t)sem_wake_count - read_ok),
         (unsigned long long)(read_period_count == 0 ? 0 :
                              read_period_min_us),
         (unsigned long long)(read_period_count == 0 ? 0 :
                              read_period_sum_us / read_period_count),
         (unsigned long long)(read_period_count == 0 ? 0 :
                              read_period_max_us));
  printf("openvela_ble_probe: IMU DRDY registers restored status=%d\n",
         restore_status);
  close(fd);
  return NULL;
}

