   396	/**
   397	 * @brief I2C memory access (There is an extra 'I2C restart' + 'I2C DevAddress' between memory address and r/w buf for memory read operation )
   398	 * @param bf0_i2c -
   399	 * @param msg_nostop  - Msg only contains memory address, msg length is memory address length
   400	 * @param msg_nostart - Msg contains read or write buffer
   401	 * @return
   402	 */
   403	static int i2c_mem_ops(struct sifli_i2c_master_s *bf0_i2c, struct i2c_msg_s * msg_nostop, struct i2c_msg_s * msg_nostart)
   404	{
   405	    int ret;
   406	    uint16_t DevAddress, MemAddress, MemAddSize;
   407	
   408	    DEBUGASSERT((1 == msg_nostop->length)||(2 == msg_nostop->length));
   409	    if (1 == msg_nostop->length)
   410	    {
   411	        MemAddSize = I2C_MEMADD_SIZE_8BIT;
   412	        MemAddress = *msg_nostop->buffer;
   413	    }
   414	    else
   415	    {
   416	        MemAddSize = I2C_MEMADD_SIZE_16BIT;
   417	
   418	        MemAddress = *(msg_nostop->buffer+1);
   419	        MemAddress = MemAddress << 8;
   420	        MemAddress |= (*msg_nostop->buffer);
   421	    }
   422	
   423	    DevAddress = msg_nostop->addr;
   424	
   425	    if (msg_nostart->flags & I2C_M_READ)
   426	    {
   427	        if (bf0_i2c->i2c_dma_flag)
   428	        {
   429	            HAL_DMA_Init(&bf0_i2c->dma.dma_rx);
   430	
   431	            ret = HAL_I2C_Mem_Read_DMA(&bf0_i2c->handle, DevAddress, MemAddress, MemAddSize, msg_nostart->buffer, msg_nostart->length);
   432	        }
   433	        else
   434	        {
   435	            #ifdef CONFIG_I2C_POLLED
   436	            ret = HAL_I2C_Mem_Read(&bf0_i2c->handle, DevAddress, MemAddress, MemAddSize, msg_nostart->buffer, msg_nostart->length, MSEC2TICK(I2C_XFER_TIMEOUT));
   437	            #else
   438	            ret = HAL_I2C_Mem_Read_IT(&bf0_i2c->handle, DevAddress, MemAddress, MemAddSize, msg_nostart->buffer, msg_nostart->length);
   439	            #endif /* CONFIG_I2C_POLLED */
   440	        }
   441	    }
   442	    else
   443	    {
   444	        if (bf0_i2c->i2c_dma_flag)
   445	        {
   446	            HAL_DMA_Init(&bf0_i2c->dma.dma_tx);
   447	            ret = HAL_I2C_Mem_Write_DMA(&bf0_i2c->handle, DevAddress, MemAddress, MemAddSize, msg_nostart->buffer, msg_nostart->length);
   448	        }
   449	        else
   450	        {
   451	            #ifdef CONFIG_I2C_POLLED
   452	            ret = HAL_I2C_Mem_Write(&bf0_i2c->handle, DevAddress, MemAddress, MemAddSize, msg_nostart->buffer, msg_nostart->length, MSEC2TICK(I2C_XFER_TIMEOUT));
   453	            #else
   454	            ret = HAL_I2C_Mem_Write_IT(&bf0_i2c->handle, DevAddress, MemAddress, MemAddSize, msg_nostart->buffer, msg_nostart->length);
   455	            #endif /* CONFIG_I2C_POLLED */
   465	 *
   466	 * Description:
   467	 *   Generic I2C transfer function
   468	 *
   469	 ****************************************************************************/
   470	static int sifli_i2c_transfer(struct i2c_master_s *dev,
   471	                                struct i2c_msg_s *msgs,
   472	                                int count)
   473	{
   474	    struct sifli_i2c_master_s *bf0_i2c;
   475	    HAL_StatusTypeDef status;
   476	    int ret;
   477	
   478	    //Mem access msg
   479	    struct i2c_msg_s * nostart_msg = NULL;
   480	    struct i2c_msg_s * nostop_msg = NULL;
   481	
   482	    DEBUGASSERT(dev != NULL);
   483	    bf0_i2c = (struct sifli_i2c_master_s *)dev;
   484	
   485	    ret = nxmutex_lock(&bf0_i2c->lock);
   486	    if (ret < 0)
   487	    {
   488	        i2cerr("i2c mutex lock failed: %d", ret);
   489	        return ret;
   490	    }
   491	
   492	    for (int index = 0; index < count; index++)
   493	    {
   494	        struct i2c_msg_s * msg = &msgs[index];
   495	
   496	        if(msg->flags & I2C_M_NOSTOP)
   497	        {
   498	            DEBUGASSERT((NULL == nostop_msg) && (NULL == nostart_msg));
   499	            nostop_msg = msg;
   500	            continue;//Memory access msg start
   501	        }
   502	        else if(msg->flags & I2C_M_NOSTART)
   503	        {
   504	            DEBUGASSERT((NULL != nostop_msg) && (NULL == nostart_msg));
   505	            nostart_msg = msg;
   506	            DEBUGASSERT(nostop_msg->frequency == nostart_msg->frequency);
   507	            DEBUGASSERT(nostop_msg->addr == nostart_msg->addr);
   508	
   509	            sifli_i2c_configure(bf0_i2c, 0, msg->frequency, msg->flags);
   510	            __HAL_I2C_ENABLE(&bf0_i2c->handle);
   511	
   512	            ret = i2c_mem_ops(bf0_i2c, nostop_msg, nostart_msg);
   513	        }
   514	        else
   515	        {
   516	            sifli_i2c_configure(bf0_i2c, 0, msg->frequency, msg->flags);
   517	            __HAL_I2C_ENABLE(&bf0_i2c->handle);
   518	            ret = i2c_normal_ops(bf0_i2c, msg);
   519	        }
   520	
   521	        while (1)
   522	        {
   523	            HAL_I2C_StateTypeDef i2c_state = HAL_I2C_GetState(&bf0_i2c->handle);
   524	
   525	            if (HAL_I2C_STATE_READY == i2c_state)
   526	            {
   527	                status = HAL_OK;
   528	            }
   529	            else if (HAL_I2C_STATE_TIMEOUT == i2c_state)
   530	            {
