   429	            HAL_DMA_Init(&bf0_i2c->dma.dma_rx);
   430	
   431	            ret = HAL_I2C_Mem_Read_DMA(&bf0_i2c->handle, DevAddress, MemAddress, MemAddSize, msg_nostart->buffer, msg_nostart->length);
   432	        }
