   304	static int probe_imu_read(int fd, uint8_t addr, uint8_t reg,
   305	                          uint8_t *value, size_t length)
   306	{
   307	  struct i2c_msg_s messages[2];
   308	
   309	  messages[0].frequency = PROBE_IMU_I2C_FREQUENCY;
   310	  messages[0].addr = addr;
   311	  messages[0].flags = I2C_M_NOSTOP;
   312	  messages[0].buffer = &reg;
   313	  messages[0].length = 1;
   314	  messages[1].frequency = PROBE_IMU_I2C_FREQUENCY;
   315	  messages[1].addr = addr;
   316	  messages[1].flags = I2C_M_READ | I2C_M_NOSTART;
   317	  messages[1].buffer = value;
   318	  messages[1].length = length;
   319	
   320	  return probe_imu_transfer(fd, messages, 2);
   321	}
