   429	static void *probe_imu_raw_thread(void *arg)
   430	{
   431	  static const uint8_t registers[5] =
   432	    {
   433	      PROBE_IMU_DRDY_PULSE_CFG_G,
   434	      PROBE_IMU_INT1_CTRL,
   435	      PROBE_IMU_CTRL1_XL,
   436	      PROBE_IMU_CTRL2_G,
   437	      PROBE_IMU_CTRL3_C
   438	    };
   439	  bool saved_valid[5] = {false, false, false, false, false};
   440	  uint8_t saved[5] = {0, 0, 0, 0, 0};
   441	  uint8_t sample[PROBE_IMU_RAW_SAMPLE_SIZE];
   442	  struct timespec start_time;
   443	  struct timespec end_time;
   444	  struct timespec wait_until;
   445	  struct timespec now;
   446	  uint64_t start_us = 0;
   447	  uint64_t end_us = 0;
   448	  uint64_t previous_read_us = 0;
   449	  uint64_t read_period_sum_us = 0;
   450	  uint64_t read_period_min_us = UINT64_MAX;
   451	  uint64_t read_period_max_us = 0;
   452	  uint64_t next_log_us;
   453	  uint32_t read_period_count = 0;
   454	  uint32_t sem_wake_count = 0;
   455	  uint32_t read_ok = 0;
   456	  uint32_t i2c_errors = 0;
   457	  uint32_t timeouts = 0;
   458	  uint32_t irq_count;
   459	  int32_t accel_mg[3] = {0, 0, 0};
   460	  int32_t gyro_mdps[3] = {0, 0, 0};
   461	  int16_t raw;
   462	  bool irq_enabled = false;
   463	  bool int1_routed = false;
   464	  int restore_status = 0;
   465	  int cleanup_ret;
   466	  int wait_status;
   467	  int fd;
   468	  int ret;
   469	  size_t i;
   470	
   471	  (void)arg;
   472	  printf("openvela_ble_probe: IMU raw thread entered\n");
   473	  __atomic_store_n(&g_imu_drdy_irq_count, 0, __ATOMIC_RELAXED);
   474	  fd = open(PROBE_IMU_I2C_DEV, O_RDONLY);
   475	  if (fd < 0)
   476	    {
   477	      printf("openvela_ble_probe: IMU raw open %s failed errno=%d\n",
   478	             PROBE_IMU_I2C_DEV, errno);
   479	      return NULL;
   480	    }
   481	
   482	  for (i = 0; i < 5; i++)
   483	    {
   484	      ret = probe_imu_read(fd, PROBE_IMU_ADDR, registers[i], &saved[i], 1);
   485	      if (ret != 0)
   486	        {
   487	          printf("openvela_ble_probe: IMU raw save reg=0x%02x failed"
   488	                 " status=%d\n", registers[i], ret);
   489	          goto restore;
   490	        }
   491	
   492	      saved_valid[i] = true;
   493	    }
   494	
   495	  ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL3_C,
   496	                               PROBE_IMU_CTRL3_C_BDU_IF_INC);
   497	  if (ret == 0)
   498	    {
   499	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL1_XL,
   500	                                   PROBE_IMU_CTRL1_XL_104HZ_4G);
   501	    }
   502	
   503	  if (ret == 0)
   504	    {
   505	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR, PROBE_IMU_CTRL2_G,
   506	                                   PROBE_IMU_CTRL2_G_104HZ_500DPS);
   507	    }
   508	
   509	  if (ret == 0)
   510	    {
   511	      ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR,
   512	                                   PROBE_IMU_DRDY_PULSE_CFG_G,
   513	                                   saved[0] & ~0x80);
   514	    }
   515	
   516	  if (ret != 0)
   517	    {
   518	      printf("openvela_ble_probe: IMU DRDY configure failed status=%d\n",
   519	             ret);
   520	      goto restore;
   521	    }
   522	
   523	  if (sem_init(&g_imu_drdy_sem, 0, 0) < 0)
   524	    {
   525	      printf("openvela_ble_probe: IMU DRDY semaphore init failed errno=%d\n",
   526	             errno);
   527	      goto restore;
   528	    }
   529	
   530	  ret = board_imu_int1_enable(probe_imu_int1_isr, NULL);
   531	  if (ret != 0)
   532	    {
   533	      printf("openvela_ble_probe: IMU DRDY IRQ enable failed status=%d\n",
   534	             ret);
   535	      sem_destroy(&g_imu_drdy_sem);
   536	      goto restore;
   537	    }
   538	
   539	  irq_enabled = true;
   540	
   541	  /* Enable only accelerometer data-ready after the host IRQ is ready. */
   542	
   543	  ret = probe_imu_write_verify(fd, PROBE_IMU_ADDR,
   544	                               PROBE_IMU_INT1_CTRL, 0x01);
   545	  if (ret != 0)
   546	    {
   547	      printf("openvela_ble_probe: IMU DRDY route failed status=%d\n", ret);
   548	      goto stop_irq;
   549	    }
   550	
   551	  int1_routed = true;
   552	
   553	  printf("openvela_ble_probe: IMU DRDY config ctrl1_xl=0x48"
   554	         " ctrl2_g=0x44 ctrl3_c=0x44 int1_ctrl=0x01 latched=1\n");
   555	
   556	  if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0)
   557	    {
   558	      printf("openvela_ble_probe: IMU DRDY clock_gettime failed errno=%d\n",
   559	             errno);
   560	      goto stop_irq;
   561	    }
   562	
   563	  end_time = start_time;
   564	  probe_timespec_add_ms(&end_time,
   565	                        BLE_PROBE_IMU_DRDY_TEST_DURATION_MS);
   566	  start_us = probe_timespec_us(&start_time);
   567	  end_us = probe_timespec_us(&end_time);
   568	  next_log_us = start_us + 10000000ULL;
   569	
   570	  for (;;)
   571	    {
   572	      uint64_t now_us;
   573	      uint64_t read_us;
   574	      uint64_t period_us;
   575	
   576	      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   577	        {
   578	          printf("openvela_ble_probe: IMU DRDY clock read failed errno=%d\n",
   579	                 errno);
   580	          break;
   581	        }
   582	
   583	      now_us = probe_timespec_us(&now);
   584	      if (now_us >= end_us)
   585	        {
   586	          break;
   587	        }
   588	
   589	      if (now_us >= next_log_us)
   590	        {
   591	          irq_count = __atomic_load_n(&g_imu_drdy_irq_count,
   592	                                      __ATOMIC_RELAXED);
   593	          printf("openvela_ble_probe: IMU DRDY progress elapsed_ms=%llu"
   594	                 " irq_count=%lu sem_wake_count=%lu read_ok=%lu"
   595	                 " i2c_errors=%lu timeouts=%lu irq_minus_wake=%ld"
   596	                 " wake_minus_read_ok=%ld accel_mg=[%ld,%ld,%ld]"
   597	                 " gyro_mdps=[%ld,%ld,%ld]\n",
   598	                 (unsigned long long)((now_us - start_us) / 1000),
   599	                 (unsigned long)irq_count, (unsigned long)sem_wake_count,
   600	                 (unsigned long)read_ok, (unsigned long)i2c_errors,
   601	                 (unsigned long)timeouts,
   602	                 (long)((int64_t)irq_count - sem_wake_count),
   603	                 (long)((int64_t)sem_wake_count - read_ok),
   604	                 (long)accel_mg[0], (long)accel_mg[1],
   605	                 (long)accel_mg[2], (long)gyro_mdps[0],
   606	                 (long)gyro_mdps[1], (long)gyro_mdps[2]);
   607	          next_log_us = now_us + 10000000ULL;
   608	        }
   609	
   610	      wait_until = now;
   611	      probe_timespec_add_ms(&wait_until, PROBE_IMU_DRDY_WAIT_MS);
   612	      if (probe_timespec_us(&wait_until) > end_us)
   613	        {
   614	          wait_until = end_time;
   615	        }
   616	
   617	      do
   618	        {
   619	          wait_status = sem_clockwait(&g_imu_drdy_sem, CLOCK_MONOTONIC,
   620	                                      &wait_until);
   621	        }
   622	      while (wait_status < 0 && errno == EINTR);
   623	
   624	      if (wait_status < 0)
   625	        {
   626	          if (errno == ETIMEDOUT)
   627	            {
   628	              timeouts++;
   629	              continue;
   630	            }
   631	
   632	          printf("openvela_ble_probe: IMU DRDY semaphore wait failed"
   633	                 " errno=%d\n", errno);
   634	          break;
   635	        }
   636	
   637	      sem_wake_count++;
   638	
   639	      ret = probe_imu_read(fd, PROBE_IMU_ADDR, PROBE_IMU_OUTX_L_G,
   640	                           sample, sizeof(sample));
   641	      if (ret != 0)
   642	        {
   643	          i2c_errors++;
   644	          continue;
   645	        }
   646	
   647	      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   648	        {
   649	          printf("openvela_ble_probe: IMU DRDY read timestamp failed"
   650	                 " errno=%d\n", errno);
   651	          break;
   652	        }
   653	
   654	      read_us = probe_timespec_us(&now);
   655	      if (previous_read_us != 0)
   656	        {
   657	          period_us = read_us - previous_read_us;
   658	          read_period_sum_us += period_us;
   659	          read_period_count++;
   660	          if (period_us < read_period_min_us)
   661	            {
   662	              read_period_min_us = period_us;
   663	            }
   664	
   665	          if (period_us > read_period_max_us)
   666	            {
   667	              read_period_max_us = period_us;
   668	            }
   669	        }
   670	
   671	      previous_read_us = read_us;
   672	
   673	      for (i = 0; i < 3; i++)
   674	        {
   675	          raw = probe_imu_get_le16(&sample[i * 2]);
   676	          gyro_mdps[i] = (int32_t)raw * 175 / 10;
   677	          raw = probe_imu_get_le16(&sample[6 + i * 2]);
   678	          accel_mg[i] = (int32_t)raw * 122 / 1000;
   679	        }
   680	
   681	      read_ok++;
   682	    }
   683	
   684	stop_irq:
   685	  if (irq_enabled)
   686	    {
   687	      cleanup_ret = board_imu_int1_disable();
   688	      if (cleanup_ret != 0 && restore_status == 0)
   689	        {
   690	          restore_status = cleanup_ret;
   691	        }
   692	      irq_enabled = false;
   693	    }
   694	
   695	  if (int1_routed)
   696	    {
   697	      cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   698	                                        PROBE_IMU_INT1_CTRL, 0x00);
   699	      if (cleanup_ret != 0 && restore_status == 0)
   700	        {
   701	          restore_status = cleanup_ret;
   702	        }
   703	    }
   704	
   705	  sem_destroy(&g_imu_drdy_sem);
   706	
   707	restore:
   708	  /* Restore controls first, then the original interrupt routing and mode. */
   709	
   710	  for (i = 2; i < 5; i++)
   711	    {
   712	      if (saved_valid[i])
   713	        {
   714	          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   715	                                            registers[i], saved[i]);
   716	          if (cleanup_ret != 0 && restore_status == 0)
   717	            {
   718	              restore_status = cleanup_ret;
   719	            }
   720	        }
   721	    }
   722	
   723	  if (saved_valid[1])
   724	    {
   725	      cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   726	                                        registers[1], saved[1]);
   727	      if (cleanup_ret != 0 && restore_status == 0)
   728	        {
   729	          restore_status = cleanup_ret;
   730	        }
   731	    }
   732	
   733	  if (saved_valid[0])
   734	    {
   735	      cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR, registers[0],
   736	                                        saved[0]);
   737	      if (cleanup_ret != 0 && restore_status == 0)
   738	        {
   739	          restore_status = cleanup_ret;
   740	        }
   741	    }
   742	
   743	  irq_count = __atomic_load_n(&g_imu_drdy_irq_count, __ATOMIC_RELAXED);
   744	  if (start_us != 0 && clock_gettime(CLOCK_MONOTONIC, &now) == 0)
   745	    {
   746	      end_us = probe_timespec_us(&now);
   747	    }
   748	
   749	  printf("openvela_ble_probe: IMU DRDY summary duration_ms=%u"
   750	         " elapsed_ms=%llu"
   751	         " irq_count=%lu sem_wake_count=%lu read_ok=%lu i2c_errors=%lu"
   752	         " timeouts=%lu irq_minus_wake=%ld wake_minus_read_ok=%ld"
   753	         " read_period_us_min=%llu avg=%llu max=%llu\n",
   754	         BLE_PROBE_IMU_DRDY_TEST_DURATION_MS,
   755	         (unsigned long long)(start_us == 0 || end_us < start_us ? 0 :
   756	                              (end_us - start_us) / 1000),
   757	         (unsigned long)irq_count, (unsigned long)sem_wake_count,
   758	         (unsigned long)read_ok, (unsigned long)i2c_errors,
   759	         (unsigned long)timeouts,
   760	         (long)((int64_t)irq_count - sem_wake_count),
   761	         (long)((int64_t)sem_wake_count - read_ok),
   762	         (unsigned long long)(read_period_count == 0 ? 0 :
   763	                              read_period_min_us),
   764	         (unsigned long long)(read_period_count == 0 ? 0 :
   765	                              read_period_sum_us / read_period_count),
   766	         (unsigned long long)(read_period_count == 0 ? 0 :
   767	                              read_period_max_us));
   768	  printf("openvela_ble_probe: IMU DRDY registers restored status=%d\n",
   769	         restore_status);
   770	  close(fd);

