                    {
                      accel_axis_mask |= 1u << (pattern_word - 3);
                      if (pattern_word == 5)
                        {
                          if (accel_axis_mask == 0x07)
                            {
                              accel_samples++;
                              if (gyro_ready)
                                {
                                  paired_samples++;
                                }
                              else
                                {
                                  unexpected_frames++;
                                }
                            }
                          else
                            {
                              unexpected_frames++;
                            }

                          accel_axis_mask = 0;
                          gyro_ready = false;
                        }
                    }
                }

              expected_pattern = (uint8_t)((pattern_word + 1) %
                                             PROBE_IMU_FIFO_PATTERN_WORDS);
              expected_valid = true;
              pattern++;
            }

