          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                            registers[i], saved[i]);
          if (cleanup_ret != 0 && restore_status == 0)
            {
              restore_status = cleanup_ret;
            }
        }
    }

  for (i = 0; i < 5; i++)
    {
      if (saved_valid[i])
        {
          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                            registers[i], saved[i]);
          if (cleanup_ret != 0 && restore_status == 0)
            {
              restore_status = cleanup_ret;
            }
        }
    }

  for (i = 5; i < 7; i++)
    {
      if (saved_valid[i])
        {
          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
                                            registers[i], saved[i]);
          if (cleanup_ret != 0 && restore_status == 0)
            {
              restore_status = cleanup_ret;
            }
        }
