                 " fifo_words_read=%lu gyro_samples=%lu accel_samples=%lu"
                 " paired_six_axis_samples=%lu fifo_overrun=%lu"
                 " fifo_smart_full=%lu max_fifo_depth_words=%lu"
                 " unexpected=%lu i2c_errors=%lu timeouts=%lu\n",
