                                 PROBE_IMU_FIFO_DATA_OUT_L,
                                 word, sizeof(word));
            if (ret != 0)
              {
                i2c_errors++;
                expected_valid = false;
                break;
              }

            fifo_words_read++;
            if (!pattern_aligned)
              {
                if (pattern_word != 0)
