 339	static int probe_imu_write_reg(int fd, uint8_t addr, uint8_t reg,
 340	                               uint8_t value)
 341	{
 342	  struct i2c_msg_s message;
 343	  uint8_t data[2] = {reg, value};
 344	
 345	  message.frequency = PROBE_IMU_I2C_FREQUENCY;
 346	  message.addr = addr;
 347	  message.flags = 0;
 348	  message.buffer = data;
 349	  message.length = sizeof(data);
 350	
 351	  return probe_imu_transfer(fd, &message, 1);
 352	}
 353	
 354	static int probe_imu_write_verify(int fd, uint8_t addr, uint8_t reg,
 355	                                  uint8_t value)
 356	{
 357	  uint8_t readback;
 358	  int ret;
 359	
 360	  ret = probe_imu_write_reg(fd, addr, reg, value);
 361	  if (ret != 0)
 362	    {
 363	      return ret;
 364	    }
 365	
 366	  ret = probe_imu_read(fd, addr, reg, &readback, 1);
 367	  if (ret != 0)
 368	    {
 369	      return ret;
 370	    }
 371	
 372	  return readback == value ? 0 : -EIO;
 373	}
