 375	static bool probe_detect_imu(void)
 376	{
 377	  static const uint8_t addresses[] = {0x6a, 0x6b};
 378	  uint8_t whoami;
 379	  bool detected = false;
 380	  int fd;
 381	  int ret;
 382	  size_t i;
 383	
 384	  fd = open(PROBE_IMU_I2C_DEV, O_RDONLY);
 385	  if (fd < 0)
 386	    {
 387	      printf("openvela_ble_probe: IMU probe open %s failed errno=%d\n",
 388	             PROBE_IMU_I2C_DEV, errno);
 389	      printf("openvela_ble_probe: IMU not detected at 0x6a or 0x6b\n");
 390	      return false;
 391	    }
 392	
 393	  for (i = 0; i < sizeof(addresses); i++)
 394	    {
 395	      whoami = 0;
 396	      ret = probe_imu_read(fd, addresses[i], PROBE_IMU_WHO_AM_I_REG,
 397	                           &whoami, 1);
 398	      printf("openvela_ble_probe: IMU probe addr=0x%02x transport=%d"
 399	             " whoami=0x%02x\n",
 400	             addresses[i], ret, whoami);
 401	      if (ret == 0 && whoami == PROBE_IMU_WHO_AM_I_VALUE)
 402	        {
 403	          printf("openvela_ble_probe: IMU detected addr=0x%02x"
 404	                 " whoami=0x6a\n", addresses[i]);
 405	          detected = true;
 406	        }
 407	    }
 408	
 409	  close(fd);
 410	  if (!detected)
 411	    {
 412	      printf("openvela_ble_probe: IMU not detected at 0x6a or 0x6b\n");
 413	    }
 414	
 415	  return detected;
 416	}
