 681	      wait_until = now;
 682	      probe_timespec_add_ms(&wait_until, PROBE_IMU_DRDY_WAIT_MS);
 683	      if (probe_timespec_us(&wait_until) > end_us)
 684	        {
 685	          wait_until = end_time;
 686	        }
 687	
 688	      do
 689	        {
 690	          wait_status = sem_clockwait(&g_imu_drdy_sem, CLOCK_MONOTONIC,
 691	                                      &wait_until);
 692	        }
 693	      while (wait_status < 0 && errno == EINTR);
