1491	  if (length == 4 && memcmp(value, "PING", 4) == 0)
1492	    {
1493	      reply = g_pong;
1494	      reply_len = sizeof(g_pong);
1495	      printf("openvela_ble_probe: RX PING\n");
1496	    }
1497	  else if (length >= 1 && value[0] == 0x01)
1498	    {
1499	      if (length < 5)
1500	        {
1501	          printf("openvela_ble_probe: short binary PING length=%u\n",
1502	                 length);
1503	          return;
1504	        }
1505	
1506	      id_or_seq = probe_get_le32(&value[1]);
1507	      response[0] = 0x81;
1508	      probe_put_le32(&response[1], id_or_seq);
1509	      printf("openvela_ble_probe: RX binary PING seq=%lu\n",
1510	             (unsigned long)id_or_seq);
1511	      status = probe_notify(srv_handle, response, 5);
1512	      printf("openvela_ble_probe: TX binary PONG status=%d\n", status);
1513	      return;
1514	    }
1515	  else if (length >= 1 && value[0] == PROBE_RELIABLE39_REQUEST_TYPE)
1516	    {
1517	      uint16_t expected_crc;
1518	      uint16_t received_crc;
1519	
1520	      if (length != PROBE_RELIABLE39_FRAME_SIZE)
1521	        {
1522	          __atomic_fetch_add(&g_reliable39_bad_length, 1,
1523	                             __ATOMIC_RELAXED);
1524	          return;
1525	        }
1526	
1527	      received_crc = probe_get_le16(&value[PROBE_RELIABLE39_CRC_OFFSET]);
1528	      expected_crc = probe_crc16_ccitt_false(
1529	        value, PROBE_RELIABLE39_CRC_OFFSET);
1530	      if (received_crc != expected_crc)
1531	        {
1532	          __atomic_fetch_add(&g_reliable39_bad_crc, 1, __ATOMIC_RELAXED);
1533	          return;
1534	        }
1535	
1536	      id_or_seq = probe_get_le32(&value[1]);
1537	      if (g_reliable39.valid &&
1538	          g_reliable39.connection_generation == connection_generation &&
1539	          g_reliable39.sequence == id_or_seq)
1540	        {
1541	          __atomic_fetch_add(&g_reliable39_duplicates, 1,
1542	                             __ATOMIC_RELAXED);
1543	        }
1544	      else
1545	        {
1546	          g_reliable39.response[0] = PROBE_RELIABLE39_RESPONSE_TYPE;
1547	          probe_put_le32(&g_reliable39.response[1], id_or_seq);
1548	          memcpy(&g_reliable39.response[5], &value[5],
1549	                 PROBE_RELIABLE39_PAYLOAD_SIZE);
1550	          probe_put_le16(&g_reliable39.response[PROBE_RELIABLE39_CRC_OFFSET],
1551	                         probe_crc16_ccitt_false(
1552	                           g_reliable39.response,
1553	                           PROBE_RELIABLE39_CRC_OFFSET));
1554	          g_reliable39.connection_generation = connection_generation;
1555	          g_reliable39.sequence = id_or_seq;
1556	          g_reliable39.valid = true;
1557	          __atomic_fetch_add(&g_reliable39_rx_ok, 1, __ATOMIC_RELAXED);
1558	        }
1559	
1560	      __atomic_fetch_add(&g_reliable39_tx_attempted, 1, __ATOMIC_RELAXED);
1561	      status = probe_notify(srv_handle, g_reliable39.response,
1562	                            sizeof(g_reliable39.response));
1563	      if (status != BT_STATUS_SUCCESS)
1564	        {
1565	          __atomic_fetch_add(&g_reliable39_tx_status_nonzero, 1,
1566	                             __ATOMIC_RELAXED);
1567	        }
1568	
1569	      return;
1570	    }
1571	  else if (length >= 1 && value[0] == PROBE_GESTURE_TIME_SYNC_TYPE)
1572	    {
1573	      if (length != 9)
1574	        {
1575	          printf("openvela_ble_probe: invalid gesture time sync length=%u\n",
1576	                 length);
1577	          return;
1578	        }
1579	
1580	      probe_gesture_time_sync(&value[1]);
1581	      return;
1582	    }
1583	  else if (length >= 1 && value[0] == PROBE_GESTURE_ACK_TYPE)
1584	    {
1585	      if (length != 3)
1586	        {
1587	          printf("openvela_ble_probe: invalid gesture ACK length=%u\n",
1588	                 length);
1589	          return;
1590	        }
1591	
1592	      probe_gesture_ack(probe_get_le16(&value[1]),
1593	                        connection_generation);
1594	      return;
1595	    }
1596	  else if (length >= 1 && value[0] == PROBE_GESTURE_INJECT_TYPE)
1597	    {
1598	      if (length != 5)
1599	        {
1600	          printf("openvela_ble_probe: invalid gesture inject length=%u\n",
1601	                 length);
1602	          return;
1603	        }
1604	
1605	#if BLE_PROBE_GESTURE_TEST_INJECT
1606	      status = probe_publish_gesture(value[1], value[2], value[3], value[4]);
1607	      printf("openvela_ble_probe: gesture test inject status=%d\n", status);
1608	#else
1609	      printf("openvela_ble_probe: gesture test inject disabled\n");
1610	#endif
1611	      return;
1612	    }
1613	  else if (length >= 1 && value[0] == 0x10)
1614	    {
1615	      if (length < 5)
1616	        {
1617	          printf("openvela_ble_probe: short START length=%u\n", length);
1618	          return;
1619	        }
1620	
1621	      id_or_seq = probe_get_le32(&value[1]);
1622	      memset(&g_throughput, 0, sizeof(g_throughput));
1623	      g_throughput.active = true;
1624	      g_throughput.test_id = id_or_seq;
1625	
1626	      response[0] = 0x90;
1627	      probe_put_le32(&response[1], id_or_seq);
1628	      printf("openvela_ble_probe: throughput START test_id=%lu\n",
1629	             (unsigned long)id_or_seq);
1630	      status = probe_notify(srv_handle, response, 5);
1631	      printf("openvela_ble_probe: throughput START_ACK status=%d\n", status);
1632	      return;
1633	    }
1634	  else if (length >= 1 && value[0] == 0x11)
1635	    {
1636	      if (length < 5)
1637	        {
1638	          printf("openvela_ble_probe: short DATA length=%u\n", length);
1639	          return;
1640	        }
1641	
1642	      if (!g_throughput.active)
1643	        {
1644	          printf("openvela_ble_probe: DATA without active test\n");
1645	          return;
1646	        }
1647	
1648	      seq = probe_get_le32(&value[1]);
1649	      if (!g_throughput.timing)
1650	        {
1651	          if (clock_gettime(CLOCK_MONOTONIC,
1652	                            &g_throughput.started_at) == 0)
1653	            {
1654	              g_throughput.timing = true;
1655	            }
1656	          else
1657	            {
1658	              printf("openvela_ble_probe: monotonic clock failed\n");
1659	            }
1660	        }
1661	
1662	      g_throughput.frames++;
1663	      g_throughput.payload_bytes += length - 5;
1664	
1665	      if (!g_throughput.have_expected_seq)
1666	        {
1667	          g_throughput.expected_seq = seq + 1;
1668	          g_throughput.have_expected_seq = true;
1669	        }
1670	      else if (seq == g_throughput.expected_seq)
1671	        {
1672	          g_throughput.expected_seq++;
1673	        }
1674	      else if (seq > g_throughput.expected_seq)
1675	        {
1676	          g_throughput.missing_frames += seq - g_throughput.expected_seq;
1677	          g_throughput.expected_seq = seq + 1;
1678	        }
1679	      else
1680	        {
1681	          g_throughput.missing_frames++;
1682	        }
1683	
1684	      return;
1685	    }
1686	  else if (length >= 1 && value[0] == 0x12)
1687	    {
1688	      if (length < 5)
1689	        {
1690	          printf("openvela_ble_probe: short END length=%u\n", length);
1691	          return;
1692	        }
1693	
1694	      id_or_seq = probe_get_le32(&value[1]);
1695	      if (!g_throughput.active || id_or_seq != g_throughput.test_id)
1696	        {
1697	          printf("openvela_ble_probe: unmatched END test_id=%lu\n",
1698	                 (unsigned long)id_or_seq);
1699	          return;
1700	        }
1701	
1702	      elapsed_ms = g_throughput.timing ?
1703	                   probe_elapsed_ms(&g_throughput.started_at) : 0;
1704	      response[0] = 0x91;
1705	      probe_put_le32(&response[1], g_throughput.test_id);
1706	      probe_put_le32(&response[5], g_throughput.frames);
1707	      probe_put_le32(&response[9], g_throughput.payload_bytes);
1708	      probe_put_le32(&response[13], elapsed_ms);
1709	      probe_put_le32(&response[17], g_throughput.missing_frames);
1710	
1711	      printf("openvela_ble_probe: throughput END test_id=%lu frames=%lu "
1712	             "payload=%lu elapsed_ms=%lu missing=%lu\n",
1713	             (unsigned long)g_throughput.test_id,
1714	             (unsigned long)g_throughput.frames,
1715	             (unsigned long)g_throughput.payload_bytes,
1716	             (unsigned long)elapsed_ms,
1717	             (unsigned long)g_throughput.missing_frames);
1718	      status = probe_notify(srv_handle, response, sizeof(response));
1719	      printf("openvela_ble_probe: throughput REPORT status=%d\n", status);
1720	      probe_print_rx_queue_stats();
1721	      memset(&g_throughput, 0, sizeof(g_throughput));
1722	      return;
1723	    }
1724	  else
1725	    {
1726	      reply = g_error;
1727	      reply_len = sizeof(g_error);
1728	      printf("openvela_ble_probe: RX unknown command\n");
1729	    }
1730	
1731	  status = probe_notify(srv_handle, reply, reply_len);
1732	  printf("openvela_ble_probe: TX notify status=%d\n", status);
1733	}
