2303	static void process_advertising_restart(void)
2304	{
2305	  static const uint16_t retry_delays_ms[PROBE_ADV_RESTART_MAX_ATTEMPTS] =
2306	    {
2307	      200, 500, 1000
2308	    };
2309	  uint64_t now_ms;
2310	  uint16_t delay_ms = 0;
2311	  uint8_t attempt = 0;
2312	  bool start_now = false;
2313	  bool log_scheduled = false;
2314	  bool retries_exhausted = false;
2315	  int ret;
2316	
2317	  if (probe_monotonic_ms(&now_ms) < 0)
2318	    {
2319	      return;
2320	    }
2321	
2322	  pthread_mutex_lock(&g_state_lock);
2323	  if (!g_adv_restart_pending || g_peer_connected ||
2324	      g_advertiser != NULL || g_adv_start_inflight)
2325	    {
2326	      pthread_mutex_unlock(&g_state_lock);
2327	      return;
2328	    }
2329	
2330	  if (g_adv_restart_attempts >= PROBE_ADV_RESTART_MAX_ATTEMPTS)
2331	    {
2332	      g_adv_restart_pending = false;
2333	      retries_exhausted = true;
2334	    }
2335	  else if (!g_adv_restart_delay_armed)
2336	    {
2337	      delay_ms = retry_delays_ms[g_adv_restart_attempts];
2338	      g_adv_restart_due_ms = now_ms + delay_ms;
2339	      g_adv_restart_delay_armed = true;
2340	      log_scheduled = true;
2341	    }
2342	  else if (now_ms >= g_adv_restart_due_ms)
2343	    {
2344	      g_adv_restart_delay_armed = false;
2345	      g_adv_restart_attempts++;
2346	      attempt = g_adv_restart_attempts;
2347	      start_now = true;
2348	    }
2349	
2350	  pthread_mutex_unlock(&g_state_lock);
2351	
2352	  if (log_scheduled)
2353	    {
2354	      printf("openvela_ble_probe: advertising restart scheduled in %u ms\n",
2355	             delay_ms);
2356	    }
2357	
2358	  if (retries_exhausted)
2359	    {
2360	      printf("openvela_ble_probe: advertising restart failed after %u "
2361	             "attempts\n", PROBE_ADV_RESTART_MAX_ATTEMPTS);
2362	      return;
2363	    }
2364	
2365	  if (!start_now)
2366	    {
2367	      return;
2368	    }
2369	
2370	  printf("openvela_ble_probe: restart advertising after disconnect "
2371	         "attempt=%u\n", attempt);
2372	  ret = start_advertising();
2373	  if (ret < 0)
2374	    {
2375	      pthread_mutex_lock(&g_state_lock);
2376	      if (g_adv_restart_pending)
2377	        {
2378	          if (g_adv_restart_attempts >= PROBE_ADV_RESTART_MAX_ATTEMPTS)
2379	            {
2380	              g_adv_restart_pending = false;
2381	              retries_exhausted = true;
2382	            }
2383	          else
2384	            {
2385	              g_adv_restart_delay_armed = false;
2386	            }
2387	        }
2388	      pthread_mutex_unlock(&g_state_lock);
2389	
2390	      if (retries_exhausted)
2391	        {
2392	          printf("openvela_ble_probe: advertising restart failed after %u "
2393	                 "attempts\n", PROBE_ADV_RESTART_MAX_ATTEMPTS);
2394	        }
2395	    }
