 223	static int probe_parse_startup_uptime(int argc, char *argv[],
 224	                                      uint64_t *target_ms)
 225	{
 226	  const char *cursor;
 227	  uint32_t value = 0;
 228	
 229	  if (argc == 1)
 230	    {
 240	            {
 241	              goto invalid;
 242	            }
 243	
 244	          value = value * 10u + (uint32_t)(*cursor - '0');
 245	          if (value > 15000u)
 246	            {
 247	              goto invalid;
 248	            }
 249	        }
 250	
 251	      if (value >= 5000u && value <= 15000u && value % 250u == 0)
 252	        {
 253	          *target_ms = value;
 254	          return 0;
 255	        }
 256	    }
 257	
 258	invalid:
 259	  printf("Usage: openvela_ble_probe "
 260	         "[min_uptime_ms: 5000..15000, step 250]\n");
 261	  return -1;
 262	}
 263	
 264	static int probe_wait_for_ble_startup(uint64_t target_ms)
 265	{
 266	  struct timespec now;
 267	  uint64_t uptime_ms;
 268	  uint64_t remaining_ms;
 269	  uint64_t sleep_ms;
 270	  bool delay_logged = false;
 271	
 272	  for (;;)
 273	    {
 274	      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
 275	        {
 276	          printf("openvela_ble_probe: failed to read system uptime\n");
 277	          return -1;
 278	        }
 279	
 280	      uptime_ms = (uint64_t)now.tv_sec * 1000u +
 281	                  (uint64_t)now.tv_nsec / 1000000u;
 282	      if (uptime_ms >= target_ms)
 283	        {
 284	          if (!delay_logged)
 285	            {
 286	              printf("openvela_ble_probe: BLE startup target=%llu ms "
 287	                     "already satisfied\n",
 288	                     (unsigned long long)target_ms);
 289	            }
 290	
 291	          return 0;
 292	        }
 293	
 294	      remaining_ms = target_ms - uptime_ms;
 295	      if (!delay_logged)
 296	        {
 297	          printf("openvela_ble_probe: delaying BLE start %llu ms "
 298	                 "for platform readiness (target=%llu ms)\n",
 299	                 (unsigned long long)remaining_ms,
 300	                 (unsigned long long)target_ms);
 301	          delay_logged = true;
 302	        }
 303	
 304	      sleep_ms = remaining_ms > 100u ? 100u : remaining_ms;
 305	      usleep((useconds_t)(sleep_ms * 1000u));
 306	    }
 307	}
