 320	static int probe_imu_read(int fd, uint8_t addr, uint8_t reg,
 321	                          uint8_t *value, size_t length)
 322	{
 323	  struct i2c_msg_s messages[2];
 324	
 325	  messages[0].frequency = PROBE_IMU_I2C_FREQUENCY;
 326	  messages[0].addr = addr;
 327	  messages[0].flags = I2C_M_NOSTOP;
 328	  messages[0].buffer = &reg;
 329	  messages[0].length = 1;
 330	  messages[1].frequency = PROBE_IMU_I2C_FREQUENCY;
 331	  messages[1].addr = addr;
 332	  messages[1].flags = I2C_M_READ | I2C_M_NOSTART;
 333	  messages[1].buffer = value;
 334	  messages[1].length = length;
 335	
 336	  return probe_imu_transfer(fd, messages, 2);
 337	}
