 424	static void probe_timespec_add_ms(struct timespec *time, uint32_t ms)
 425	{
 426	  uint64_t nsec = (uint64_t)time->tv_nsec +
 427	                  (uint64_t)ms * 1000000ULL;
 428	
 429	  time->tv_sec += (time_t)(nsec / 1000000000ULL);
 430	  time->tv_nsec = (long)(nsec % 1000000000ULL);
 431	}
