 633	  end_us = probe_timespec_us(&end_time);
 634	  next_log_us = start_us + 10000000ULL;
 635	
 636	  for (;;)
 637	    {
 638	      uint64_t now_us;
 639	      bool wake_watermark_seen = false;
 640	      bool wake_smart_full_seen = false;
 641	      bool wake_overrun_seen = false;
