 652	        {
 653	          break;
 654	        }
 655	
 656	      if (now_us >= next_log_us)
 657	        {
 658	          fifo_irq_count = __atomic_load_n(&g_imu_drdy_irq_count,
 659	                                           __ATOMIC_RELAXED);
 660	          printf("openvela_ble_probe: IMU FIFO progress elapsed_ms=%llu"
 661	                 " fifo_irq_count=%lu fifo_wake_count=%lu"
 662	                 " fifo_words_read=%lu gyro_samples=%lu accel_samples=%lu"
 663	                 " paired_six_axis_samples=%lu fifo_overrun=%lu"
 664	                 " fifo_smart_full=%lu max_fifo_depth_words=%lu"
 665	                 " unexpected=%lu i2c_errors=%lu timeouts=%lu\n",
 666	                 (unsigned long long)((now_us - start_us) / 1000),
 667	                 (unsigned long)fifo_irq_count,
 668	                 (unsigned long)fifo_wake_count,
 669	                 (unsigned long)fifo_words_read,
 670	                 (unsigned long)gyro_samples,
 671	                 (unsigned long)accel_samples,
 672	                 (unsigned long)paired_samples,
 673	                 (unsigned long)fifo_overrun,
 674	                 (unsigned long)fifo_smart_full,
 675	                 (unsigned long)max_fifo_depth_words,
 676	                 (unsigned long)unexpected_frames,
 677	                 (unsigned long)i2c_errors, (unsigned long)timeouts);
 678	          next_log_us = now_us + 10000000ULL;
 679	        }
 680	
 681	      wait_until = now;
 682	      probe_timespec_add_ms(&wait_until, PROBE_IMU_DRDY_WAIT_MS);
 683	      if (probe_timespec_us(&wait_until) > end_us)
