1898	static void on_gatts_connected(gatts_handle_t srv_handle, bt_address_t *addr)
1899	{
1900	  (void)srv_handle;
1901	
1902	  pthread_mutex_lock(&g_state_lock);
1903	  __atomic_add_fetch(&g_connection_generation, 1, __ATOMIC_RELEASE);
1904	  __atomic_store_n(&g_rx_enqueued, 0, __ATOMIC_RELAXED);
1905	  __atomic_store_n(&g_rx_invalid_length, 0, __ATOMIC_RELAXED);
1906	  __atomic_store_n(&g_rx_drop_lock_busy, 0, __ATOMIC_RELAXED);
1907	  __atomic_store_n(&g_rx_drop_full, 0, __ATOMIC_RELAXED);
1908	  __atomic_store_n(&g_rx_high_water, 0, __ATOMIC_RELAXED);
1909	  __atomic_store_n(&g_rx_stale, 0, __ATOMIC_RELAXED);
1910	  __atomic_store_n(&g_reliable39_rx_ok, 0, __ATOMIC_RELAXED);
1911	  __atomic_store_n(&g_reliable39_bad_length, 0, __ATOMIC_RELAXED);
1912	  __atomic_store_n(&g_reliable39_bad_crc, 0, __ATOMIC_RELAXED);
1913	  __atomic_store_n(&g_reliable39_duplicates, 0, __ATOMIC_RELAXED);
1914	  __atomic_store_n(&g_reliable39_tx_attempted, 0, __ATOMIC_RELAXED);
1915	  __atomic_store_n(&g_reliable39_tx_status_nonzero, 0, __ATOMIC_RELAXED);
1916	  memset(g_gesture_queue, 0, sizeof(g_gesture_queue));
1917	  g_gesture_rx_head = 0;
1918	  g_gesture_rx_tail = 0;
1919	  g_gesture_next_packet_id = 1;
1920	  g_gesture_time_synced = false;
1921	  g_gesture_sync_unix_ms = 0;
1922	  g_gesture_sync_monotonic_ms = 0;
1923	  g_gesture_enqueued = 0;
1924	  g_gesture_queue_full = 0;
1925	  g_gesture_acked = 0;
1926	  g_gesture_retransmitted = 0;
1927	  g_gesture_dropped = 0;
1928	  g_gesture_tx_status_nonzero = 0;
1929	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
1930	  g_notify_enabled = false;
1931	  g_phy_read_requested = false;
1932	  g_phy_update_requested = false;
1933	  g_phy_update_pending = false;
1934	  g_peer_connected = true;
1935	  g_adv_restart_pending = false;
1936	  g_adv_restart_delay_armed = false;
1937	  g_adv_restart_attempts = 0;
1938	#if BLE_PROBE_ENABLE_AUTO_2M_PHY
1939	  g_phy_read_pending = true;
1940	#else
1941	  g_phy_read_pending = false;
1942	#endif
1943	  pthread_mutex_unlock(&g_state_lock);
1944	  printf("openvela_ble_probe: GATT client connected\n");
1945	#if !BLE_PROBE_ENABLE_AUTO_2M_PHY
1946	  printf("openvela_ble_probe: automatic 2M PHY request disabled\n");
1947	#endif
1948	}
