   264	static int probe_wait_for_ble_startup(uint64_t target_ms)
   265	{
   266	  struct timespec now;
   267	  uint64_t uptime_ms;
   268	  uint64_t remaining_ms;
   269	  uint64_t sleep_ms;
   270	  bool delay_logged = false;
   271	
   272	  for (;;)
   273	    {
   274	      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
   275	        {
   276	          printf("openvela_ble_probe: failed to read system uptime\n");
   277	          return -1;
   278	        }
   279	
   280	      uptime_ms = (uint64_t)now.tv_sec * 1000u +
   281	                  (uint64_t)now.tv_nsec / 1000000u;
   282	      if (uptime_ms >= target_ms)
   283	        {
   284	          if (!delay_logged)
   285	            {
