1229	/* Future gesture producers must use this bounded publisher rather than
1230	 * calling a GATT API.  It is task-context only, never ISR-context.
1231	 */
1232	
1233	static int probe_publish_gesture(uint8_t gesture, uint8_t confidence,
1234	                                 uint8_t flags, uint8_t battery)
1235	{
1236	  struct probe_gesture_record_s *record;
1237	  uint64_t monotonic_ms;
1238	  uint64_t timestamp_ms;
1239	  uint32_t generation;
1240	  uint32_t used;
1241	  bool synced;
1242	
1243	  if (probe_monotonic_ms(&monotonic_ms) < 0)
1244	    {
1245	      return -1;
1246	    }
1247	
1248	  pthread_mutex_lock(&g_state_lock);
1249	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
1250	  if (!g_peer_connected)
1251	    {
1252	      pthread_mutex_unlock(&g_state_lock);
1253	      return -1;
1254	    }
1255	
1256	  used = g_gesture_rx_head - g_gesture_rx_tail;
1257	  if (used >= PROBE_GESTURE_QUEUE_DEPTH)
1258	    {
1259	      g_gesture_queue_full++;
1260	      pthread_mutex_unlock(&g_state_lock);
1261	      return -1;
1262	    }
1263	
1264	  synced = g_gesture_time_synced;
1265	  timestamp_ms = synced ?
1266	    g_gesture_sync_unix_ms +
1267	      (monotonic_ms - g_gesture_sync_monotonic_ms) : monotonic_ms;
1268	  if (synced)
1269	    {
1270	      flags |= 0x01;
1271	    }
1272	  else
1273	    {
1274	      flags &= (uint8_t)~0x01;
1275	    }
1276	
1277	  record = &g_gesture_queue[g_gesture_rx_head %
1278	                            PROBE_GESTURE_QUEUE_DEPTH];
1279	  memset(record, 0, sizeof(*record));
1280	  record->connection_generation = generation;
1281	  record->packet_id = g_gesture_next_packet_id++;
1282	  record->event[0] = 1;
1283	  record->event[1] = 0x01;
1284	  probe_put_le16(&record->event[2], record->packet_id);
1285	  probe_put_le64(&record->event[4], timestamp_ms);
1286	  record->event[12] = gesture;
1287	  record->event[13] = confidence;
1288	  record->event[14] = flags;
1289	  record->event[15] = battery;
1290	  g_gesture_rx_head++;
1291	  g_gesture_enqueued++;
1292	  pthread_mutex_unlock(&g_state_lock);
1293	
1294	  sem_post(&g_rx_sem);
1295	  return 0;
1296	}
1297	
1298	static void probe_gesture_time_sync(const uint8_t *value)
1299	{
1300	  uint64_t monotonic_ms;
1301	
1302	  if (probe_monotonic_ms(&monotonic_ms) < 0)
1303	    {
1304	      printf("openvela_ble_probe: gesture time sync clock failed\n");
1305	      return;
1306	    }
1307	
1308	  pthread_mutex_lock(&g_state_lock);
1309	  g_gesture_sync_unix_ms = probe_get_le64(value);
1310	  g_gesture_sync_monotonic_ms = monotonic_ms;
1311	  g_gesture_time_synced = true;
1312	  pthread_mutex_unlock(&g_state_lock);
1313	  printf("openvela_ble_probe: gesture time synchronized\n");
1314	}
