1316	static void probe_gesture_ack(uint16_t packet_id, uint32_t generation)
1317	{
1318	  struct probe_gesture_record_s *record;
1319	  bool matched = false;
1320	
1321	  pthread_mutex_lock(&g_state_lock);
1322	  if (g_gesture_rx_tail != g_gesture_rx_head)
1323	    {
1324	      record = &g_gesture_queue[g_gesture_rx_tail %
1325	                                PROBE_GESTURE_QUEUE_DEPTH];
1326	      if (record->connection_generation == generation &&
1327	          record->packet_id == packet_id && record->send_count != 0)
1328	        {
1329	          memset(record, 0, sizeof(*record));
1330	          g_gesture_rx_tail++;
1331	          g_gesture_acked++;
1332	          matched = true;
1333	        }
1334	    }
1335	  pthread_mutex_unlock(&g_state_lock);
1336	
1337	  if (matched)
1338	    {
1339	      printf("openvela_ble_probe: gesture ACK packet_id=%u\n", packet_id);
1340	    }
1341	}
