1479	static void probe_process_frame(gatts_handle_t srv_handle,
1480	                                const uint8_t *value, uint16_t length,
1481	                                uint32_t connection_generation)
1482	{
1483	  uint8_t response[21];
1484	  uint8_t *reply;
1485	  uint16_t reply_len;
1486	  uint32_t elapsed_ms;
1487	  uint32_t id_or_seq;
1488	  uint32_t seq;
1489	  bt_status_t status;
1490	
1491	  if (length == 4 && memcmp(value, "PING", 4) == 0)
1492	    {
1493	      reply = g_pong;
1494	      reply_len = sizeof(g_pong);
1495	      printf("openvela_ble_probe: RX PING\n");
1496	    }
1497	  else if (length >= 1 && value[0] == 0x01)
1498	    {
1499	      if (length < 5)
1500	        {
1501	          printf("openvela_ble_probe: short binary PING length=%u\n",
1502	                 length);
1503	          return;
1504	        }
1505	
1506	      id_or_seq = probe_get_le32(&value[1]);
1507	      response[0] = 0x81;
1508	      probe_put_le32(&response[1], id_or_seq);
1509	      printf("openvela_ble_probe: RX binary PING seq=%lu\n",
1510	             (unsigned long)id_or_seq);
1511	      status = probe_notify(srv_handle, response, 5);
1512	      printf("openvela_ble_probe: TX binary PONG status=%d\n", status);
1513	      return;
1514	    }
1515	  else if (length >= 1 && value[0] == PROBE_RELIABLE39_REQUEST_TYPE)
1516	    {
1517	      uint16_t expected_crc;
1518	      uint16_t received_crc;
1519	
1520	      if (length != PROBE_RELIABLE39_FRAME_SIZE)
1521	        {
1522	          __atomic_fetch_add(&g_reliable39_bad_length, 1,
1523	                             __ATOMIC_RELAXED);
1524	          return;
1525	        }
1526	
1527	      received_crc = probe_get_le16(&value[PROBE_RELIABLE39_CRC_OFFSET]);
1528	      expected_crc = probe_crc16_ccitt_false(
1529	        value, PROBE_RELIABLE39_CRC_OFFSET);
1530	      if (received_crc != expected_crc)
1531	        {
1532	          __atomic_fetch_add(&g_reliable39_bad_crc, 1, __ATOMIC_RELAXED);
1533	          return;
1534	        }
1535	
1536	      id_or_seq = probe_get_le32(&value[1]);
1537	      if (g_reliable39.valid &&
1538	          g_reliable39.connection_generation == connection_generation &&
1539	          g_reliable39.sequence == id_or_seq)
1540	        {
1541	          __atomic_fetch_add(&g_reliable39_duplicates, 1,
1542	                             __ATOMIC_RELAXED);
1543	        }
1544	      else
1545	        {
1546	          g_reliable39.response[0] = PROBE_RELIABLE39_RESPONSE_TYPE;
1547	          probe_put_le32(&g_reliable39.response[1], id_or_seq);
1548	          memcpy(&g_reliable39.response[5], &value[5],
1549	                 PROBE_RELIABLE39_PAYLOAD_SIZE);
1550	          probe_put_le16(&g_reliable39.response[PROBE_RELIABLE39_CRC_OFFSET],
1551	                         probe_crc16_ccitt_false(
1552	                           g_reliable39.response,
1553	                           PROBE_RELIABLE39_CRC_OFFSET));
1554	          g_reliable39.connection_generation = connection_generation;
1555	          g_reliable39.sequence = id_or_seq;
1556	          g_reliable39.valid = true;
1557	          __atomic_fetch_add(&g_reliable39_rx_ok, 1, __ATOMIC_RELAXED);
1558	        }
1559	
1560	      __atomic_fetch_add(&g_reliable39_tx_attempted, 1, __ATOMIC_RELAXED);
1561	      status = probe_notify(srv_handle, g_reliable39.response,
1562	                            sizeof(g_reliable39.response));
1563	      if (status != BT_STATUS_SUCCESS)
1564	        {
1565	          __atomic_fetch_add(&g_reliable39_tx_status_nonzero, 1,
1566	                             __ATOMIC_RELAXED);
1567	        }
1568	
1569	      return;
1570	    }
1571	  else if (length >= 1 && value[0] == PROBE_GESTURE_TIME_SYNC_TYPE)
1572	    {
1573	      if (length != 9)
1574	        {
1575	          printf("openvela_ble_probe: invalid gesture time sync length=%u\n",
1576	                 length);
1577	          return;
1578	        }
1579	
1580	      probe_gesture_time_sync(&value[1]);
1581	      return;
1582	    }
1583	  else if (length >= 1 && value[0] == PROBE_GESTURE_ACK_TYPE)
1584	    {
1585	      if (length != 3)
1586	        {
1587	          printf("openvela_ble_probe: invalid gesture ACK length=%u\n",
1588	                 length);
1589	          return;
1590	        }
1591	
1592	      probe_gesture_ack(probe_get_le16(&value[1]),
1593	                        connection_generation);
1594	      return;
1595	    }
1596	  else if (length >= 1 && value[0] == PROBE_GESTURE_INJECT_TYPE)
1597	    {
1598	      if (length != 5)
1599	        {
1600	          printf("openvela_ble_probe: invalid gesture inject length=%u\n",
1601	                 length);
1602	          return;
1603	        }
1604	
1605	#if BLE_PROBE_GESTURE_TEST_INJECT
1606	      status = probe_publish_gesture(value[1], value[2], value[3], value[4]);
1607	      printf("openvela_ble_probe: gesture test inject status=%d\n", status);
1608	#else
1609	      printf("openvela_ble_probe: gesture test inject disabled\n");
1610	#endif
1611	      return;
1612	    }
1613	  else if (length >= 1 && value[0] == 0x10)
1614	    {
1615	      if (length < 5)
1616	        {
1617	          printf("openvela_ble_probe: short START length=%u\n", length);
1618	          return;
1619	        }
1620	
1725	    {
1726	      reply = g_error;
1727	      reply_len = sizeof(g_error);
1728	      printf("openvela_ble_probe: RX unknown command\n");
1729	    }
1730	
1731	  status = probe_notify(srv_handle, reply, reply_len);
1732	  printf("openvela_ble_probe: TX notify status=%d\n", status);
1733	}
1734	
1735	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
1736	                                 bt_address_t *addr,
1737	                                 uint16_t attr_handle,
1738	                                 const uint8_t *value,
1739	                                 uint16_t length,
1740	                                 uint16_t offset)
1741	{
1742	  struct probe_rx_slot_s *slot;
1743	  uint32_t generation;
1744	  uint32_t head;
1745	  uint32_t tail;
1746	  uint32_t used;
1747	
1748	  (void)srv_handle;
1749	  (void)attr_handle;
1750	
1751	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
1752	    {
1753	      __atomic_fetch_add(&g_rx_invalid_length, 1, __ATOMIC_RELAXED);
1754	      return 0;
1755	    }
1756	
1757	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
1758	  head = __atomic_load_n(&g_rx_head, __ATOMIC_RELAXED);
1759	  tail = __atomic_load_n(&g_rx_tail, __ATOMIC_ACQUIRE);
1760	  used = head - tail;
1761	  if (used >= PROBE_RX_QUEUE_DEPTH)
1762	    {
1763	      __atomic_fetch_add(&g_rx_drop_full, 1, __ATOMIC_RELAXED);
1764	      return 0;
1765	    }
1766	
1767	  slot = &g_rx_queue[head % PROBE_RX_QUEUE_DEPTH];
1768	  memcpy(&slot->addr, addr, sizeof(slot->addr));
1769	  slot->connection_generation = generation;
1770	  slot->length = length;
1771	  slot->offset = offset;
1772	  memcpy(slot->value, value, length);
1773	  used++;
1774	  if (used >
1775	      __atomic_load_n(&g_rx_high_water, __ATOMIC_RELAXED))
1776	    {
1777	      __atomic_store_n(&g_rx_high_water, used, __ATOMIC_RELAXED);
1778	    }
1779	
1780	  /* Publish only after the complete slot is visible to the consumer. */
1781	
1782	  __atomic_store_n(&g_rx_head, head + 1, __ATOMIC_RELEASE);
1783	
1784	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
1785	  sem_post(&g_rx_sem);
1786	  return length;
1787	}
1788	
1789	static void *probe_communication_thread(void *arg)
1790	{
1791	  struct probe_rx_slot_s slot;
1792	  bt_address_t peer_addr;
1793	  uint32_t generation;
1794	  uint32_t active_generation = 0;
1795	  uint32_t head;
1796	  uint32_t tail;
1797	  bool connected;
1798	  bool have_slot;
1799	  int wait_status;
1800	  struct timespec wait_until;
1801	
1802	  (void)arg;
1803	
1804	  for (;;)
1805	    {
1806	      if (clock_gettime(CLOCK_REALTIME, &wait_until) < 0)
1807	        {
1808	          continue;
1809	        }
1810	
1811	      wait_until.tv_nsec += PROBE_GESTURE_WORKER_POLL_MS * 1000000L;
1812	      if (wait_until.tv_nsec >= 1000000000L)
1813	        {
1814	          wait_until.tv_sec++;
1815	          wait_until.tv_nsec -= 1000000000L;
1816	        }
1817	
1818	      do
1819	        {
1820	          wait_status = sem_timedwait(&g_rx_sem, &wait_until);
1821	        }
1822	      while (wait_status < 0 && errno == EINTR);
1823	
1824	      if (wait_status < 0 && errno != ETIMEDOUT)
1825	        {
1826	          continue;
1827	        }
1828	
1829	      tail = __atomic_load_n(&g_rx_tail, __ATOMIC_RELAXED);
1830	      head = __atomic_load_n(&g_rx_head, __ATOMIC_ACQUIRE);
1831	      have_slot = tail != head;
1832	      if (have_slot)
1833	        {
1834	          memcpy(&slot, &g_rx_queue[tail % PROBE_RX_QUEUE_DEPTH],
1835	                 sizeof(slot));
1836	          __atomic_store_n(&g_rx_tail, tail + 1, __ATOMIC_RELEASE);
1837	        }
1838	
1839	      pthread_mutex_lock(&g_state_lock);
1840	      generation = __atomic_load_n(&g_connection_generation,
1841	                                   __ATOMIC_ACQUIRE);
1842	      connected = g_peer_connected;
1843	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
1844	      pthread_mutex_unlock(&g_state_lock);
1845	
1846	      if (generation != active_generation)
1847	        {
1848	          memset(&g_throughput, 0, sizeof(g_throughput));
1849	          memset(&g_reliable39, 0, sizeof(g_reliable39));
1850	          active_generation = generation;
1851	        }
1852	
1853	      if (have_slot &&
1854	          (!connected || slot.connection_generation != generation ||
1855	           memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0))
1856	        {
1857	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
1858	          have_slot = false;
1859	        }
1860	
1861	      if (have_slot)
1862	        {
1863	          probe_process_frame(g_service_handle, slot.value, slot.length,
1864	                              generation);
1865	        }
1866	
1867	      probe_process_gesture_tx();
1868	    }
1869	
1870	  return NULL;
1871	}
