1444	
1445	  (void)srv_handle;
1446	  (void)attr_handle;
1447	
1448	  if (offset != 0 || length < 2)
1449	    {
1450	      printf("openvela_ble_probe: invalid CCCD write\n");
1451	      return 0;
1452	    }
1453	
1454	  cccd = (uint16_t)value[0] | ((uint16_t)value[1] << 8);
1455	  pthread_mutex_lock(&g_state_lock);
1456	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
1457	  g_notify_enabled = (cccd & GATT_CCC_NOTIFY) != 0;
1458	  notify_enabled = g_notify_enabled;
1459	#if BLE_PROBE_IMU_DRDY_START_ON_TX_SUBSCRIBE
1460	  if (notify_enabled && g_peer_connected && g_imu_detected &&
1461	      !g_imu_raw_launch_pending && !g_imu_raw_launch_attempted &&
1462	      !g_imu_raw_started)
1463	    {
1464	      g_imu_raw_launch_pending = true;
1465	      schedule_imu = true;
1466	    }
1467	#endif
1468	  pthread_mutex_unlock(&g_state_lock);
1469	
1470	  printf("openvela_ble_probe: TX notify=%d\n", notify_enabled);
1471	  if (schedule_imu)
1472	    {
1473	      printf("openvela_ble_probe: IMU DRDY soak start requested by TX"
1474	             " subscription\n");
1475	    }
1476	  return length;
1477	}
