1735	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
1736	                                 bt_address_t *addr,
1737	                                 uint16_t attr_handle,
1738	                                 const uint8_t *value,
1739	                                 uint16_t length,
1740	                                 uint16_t offset)
1741	{
1742	  struct probe_rx_slot_s *slot;
1743	  uint32_t generation;
1744	  uint32_t head;
1745	  uint32_t tail;
1746	  uint32_t used;
1747	
1748	  (void)srv_handle;
1749	  (void)attr_handle;
1750	
1751	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
1752	    {
1753	      __atomic_fetch_add(&g_rx_invalid_length, 1, __ATOMIC_RELAXED);
1754	      return 0;
1755	    }
1756	
1757	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
1758	  head = __atomic_load_n(&g_rx_head, __ATOMIC_RELAXED);
1759	  tail = __atomic_load_n(&g_rx_tail, __ATOMIC_ACQUIRE);
1760	  used = head - tail;
1761	  if (used >= PROBE_RX_QUEUE_DEPTH)
1762	    {
1763	      __atomic_fetch_add(&g_rx_drop_full, 1, __ATOMIC_RELAXED);
1764	      return 0;
1765	    }
1766	
1767	  slot = &g_rx_queue[head % PROBE_RX_QUEUE_DEPTH];
1768	  memcpy(&slot->addr, addr, sizeof(slot->addr));
1769	  slot->connection_generation = generation;
1770	  slot->length = length;
1771	  slot->offset = offset;
1772	  memcpy(slot->value, value, length);
1773	  used++;
1774	  if (used >
1775	      __atomic_load_n(&g_rx_high_water, __ATOMIC_RELAXED))
1776	    {
1777	      __atomic_store_n(&g_rx_high_water, used, __ATOMIC_RELAXED);
1778	    }
1779	
1780	  /* Publish only after the complete slot is visible to the consumer. */
1781	
1782	  __atomic_store_n(&g_rx_head, head + 1, __ATOMIC_RELEASE);
1783	
1784	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
1785	  sem_post(&g_rx_sem);
1786	  return length;
1787	}
1788	
1789	static void *probe_communication_thread(void *arg)
1790	{
1791	  struct probe_rx_slot_s slot;
1792	  bt_address_t peer_addr;
1793	  uint32_t generation;
1794	  uint32_t active_generation = 0;
1795	  uint32_t head;
1796	  uint32_t tail;
1797	  bool connected;
1798	  bool have_slot;
1799	  int wait_status;
1800	  struct timespec wait_until;
1801	
1802	  (void)arg;
1803	
1804	  for (;;)
1805	    {
1806	      if (clock_gettime(CLOCK_REALTIME, &wait_until) < 0)
1807	        {
1808	          continue;
1809	        }
1810	
1811	      wait_until.tv_nsec += PROBE_GESTURE_WORKER_POLL_MS * 1000000L;
1812	      if (wait_until.tv_nsec >= 1000000000L)
1813	        {
1814	          wait_until.tv_sec++;
1815	          wait_until.tv_nsec -= 1000000000L;
1816	        }
1817	
1818	      do
1819	        {
1820	          wait_status = sem_timedwait(&g_rx_sem, &wait_until);
1821	        }
1822	      while (wait_status < 0 && errno == EINTR);
1823	
1824	      if (wait_status < 0 && errno != ETIMEDOUT)
1825	        {
1826	          continue;
1827	        }
1828	
1829	      tail = __atomic_load_n(&g_rx_tail, __ATOMIC_RELAXED);
1830	      head = __atomic_load_n(&g_rx_head, __ATOMIC_ACQUIRE);
1831	      have_slot = tail != head;
1832	      if (have_slot)
1833	        {
1834	          memcpy(&slot, &g_rx_queue[tail % PROBE_RX_QUEUE_DEPTH],
1835	                 sizeof(slot));
1836	          __atomic_store_n(&g_rx_tail, tail + 1, __ATOMIC_RELEASE);
1837	        }
1838	
1839	      pthread_mutex_lock(&g_state_lock);
1840	      generation = __atomic_load_n(&g_connection_generation,
1841	                                   __ATOMIC_ACQUIRE);
1842	      connected = g_peer_connected;
1843	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
1844	      pthread_mutex_unlock(&g_state_lock);
1845	
1846	      if (generation != active_generation)
1847	        {
1848	          memset(&g_throughput, 0, sizeof(g_throughput));
1849	          memset(&g_reliable39, 0, sizeof(g_reliable39));
1850	          active_generation = generation;
1851	        }
1852	
1853	      if (have_slot &&
1854	          (!connected || slot.connection_generation != generation ||
1855	           memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0))
1856	        {
1857	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
1858	          have_slot = false;
1859	        }
1860	
1861	      if (have_slot)
1862	        {
1863	          probe_process_frame(g_service_handle, slot.value, slot.length,
1864	                              generation);
1865	        }
1866	
1867	      probe_process_gesture_tx();
1868	    }
1869	
1870	  return NULL;
1871	}
