1343	static void probe_process_gesture_tx(void)
1344	{
1345	  static const uint16_t retry_delays_ms[PROBE_GESTURE_MAX_SENDS] =
1346	    {
1347	      500, 1000, 2000
1348	    };
1349	  struct probe_gesture_record_s *record;
1350	  uint8_t event[PROBE_GESTURE_EVENT_SIZE];
1351	  uint64_t now_ms;
1352	  uint32_t generation;
1353	  uint16_t packet_id = 0;
1354	  uint8_t send_count = 0;
1355	  bool send = false;
1356	  bool dropped = false;
1357	  bt_status_t status;
1358	
1359	  if (probe_monotonic_ms(&now_ms) < 0)
1360	    {
1361	      return;
1362	    }
1363	
1364	  pthread_mutex_lock(&g_state_lock);
1365	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
1366	  if (g_gesture_rx_tail != g_gesture_rx_head)
1367	    {
1368	      record = &g_gesture_queue[g_gesture_rx_tail %
1369	                                PROBE_GESTURE_QUEUE_DEPTH];
1370	      if (!g_peer_connected || !g_notify_enabled ||
1371	          record->connection_generation != generation)
1372	        {
1373	          if (record->connection_generation != generation)
1374	            {
1375	              g_gesture_rx_tail = g_gesture_rx_head;
1376	            }
1377	        }
1378	      else if (record->send_count == 0 || now_ms >= record->next_retry_ms)
1379	        {
1380	          if (record->send_count >= PROBE_GESTURE_MAX_SENDS)
1381	            {
1382	              packet_id = record->packet_id;
1383	              memset(record, 0, sizeof(*record));
1384	              g_gesture_rx_tail++;
1385	              g_gesture_dropped++;
1386	              dropped = true;
1387	            }
1388	          else
1389	            {
1390	              packet_id = record->packet_id;
1391	              memcpy(event, record->event, sizeof(event));
1392	              record->send_count++;
1393	              send_count = record->send_count;
1394	              record->next_retry_ms =
1395	                now_ms + retry_delays_ms[send_count - 1];
1396	              if (send_count > 1)
1397	                {
1398	                  g_gesture_retransmitted++;
1399	                }
1400	              send = true;
1401	            }
1402	        }
1403	    }
1404	  pthread_mutex_unlock(&g_state_lock);
1405	
1406	  if (dropped)
1407	    {
1408	      printf("openvela_ble_probe: gesture dropped packet_id=%u\n",
1409	             packet_id);
1410	      return;
1411	    }
1412	
1413	  if (!send)
1414	    {
1415	      return;
1416	    }
1417	
1418	  status = probe_notify(g_service_handle, event, sizeof(event));
1419	  if (status != BT_STATUS_SUCCESS)
1420	    {
1421	      pthread_mutex_lock(&g_state_lock);
1422	      g_gesture_tx_status_nonzero++;
1423	      pthread_mutex_unlock(&g_state_lock);
1424	    }
1425	
1426	  if (send_count > 1)
1427	    {
1428	      printf("openvela_ble_probe: gesture retransmit packet_id=%u "
1429	             "attempt=%u status=%d\n",
1430	             packet_id, send_count, status);
1431	    }
1432	}
