1735	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
1736	                                 bt_address_t *addr,
1737	                                 uint16_t attr_handle,
1738	                                 const uint8_t *value,
1739	                                 uint16_t length,
1740	                                 uint16_t offset)
1741	{
1742	  struct probe_rx_slot_s *slot;
1743	  uint32_t generation;
1744	  uint32_t head;
1745	  uint32_t tail;
1746	  uint32_t used;
1747	
1748	  (void)srv_handle;
1749	  (void)attr_handle;
1750	
1751	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
1752	    {
1753	      __atomic_fetch_add(&g_rx_invalid_length, 1, __ATOMIC_RELAXED);
1754	      return 0;
1755	    }
1756	
1757	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
1758	  head = __atomic_load_n(&g_rx_head, __ATOMIC_RELAXED);
1759	  tail = __atomic_load_n(&g_rx_tail, __ATOMIC_ACQUIRE);
1760	  used = head - tail;
1761	  if (used >= PROBE_RX_QUEUE_DEPTH)
1762	    {
1763	      __atomic_fetch_add(&g_rx_drop_full, 1, __ATOMIC_RELAXED);
1764	      return 0;
1765	    }
1766	
1767	  slot = &g_rx_queue[head % PROBE_RX_QUEUE_DEPTH];
1768	  memcpy(&slot->addr, addr, sizeof(slot->addr));
1769	  slot->connection_generation = generation;
1770	  slot->length = length;
1771	  slot->offset = offset;
1772	  memcpy(slot->value, value, length);
1773	  used++;
1774	  if (used >
1775	      __atomic_load_n(&g_rx_high_water, __ATOMIC_RELAXED))
1776	    {
1777	      __atomic_store_n(&g_rx_high_water, used, __ATOMIC_RELAXED);
1778	    }
1779	
1780	  /* Publish only after the complete slot is visible to the consumer. */
1781	
1782	  __atomic_store_n(&g_rx_head, head + 1, __ATOMIC_RELEASE);
1783	
1784	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
1785	  sem_post(&g_rx_sem);
1786	  return length;
1787	}
