596	static bt_status_t if_gatts_add_attr_table(void* srv_handle, gatt_srv_db_t* srv_db)
597	{
598	    gatts_service_t* service = srv_handle;
599	
600	    CHECK_ENABLED();
601	    CHECK_SERVICE_VALID(g_gatts_manager.services, service);
602	
603	    service_table_t* svc_table = find_service_table_by_id(service, srv_db->attr_db[0].handle + service->srv_id);
604	    if (svc_table)
605	        return BT_STATUS_PARM_INVALID;
606	
607	    svc_table = service_table_new(srv_db->attr_num);
608	    if (svc_table == NULL)
609	        return BT_STATUS_NOMEM;
610	
611	    gatt_element_t* elements = svc_table->elements;
612	    gatt_attr_db_t* attr_inst = srv_db->attr_db;
613	    for (int i = 0; i < srv_db->attr_num; i++, elements++, attr_inst++) {
614	
615	        elements->handle = service->srv_id + attr_inst->handle;
616	        elements->type = attr_inst->type;
617	        elements->properties = attr_inst->properties;
618	        elements->permissions = attr_inst->permissions;
619	        elements->rsp_type = attr_inst->rsp_type;
620	        elements->read_cb = attr_inst->read_cb;
621	        elements->write_cb = attr_inst->write_cb;
622	        elements->attr_length = attr_inst->attr_length;
623	        elements->attr_data = NULL;
624	        if (elements->rsp_type == ATTR_AUTO_RSP && elements->attr_length) {
625	            elements->attr_data = malloc(elements->attr_length);
626	            memcpy(elements->attr_data, attr_inst->attr_value, elements->attr_length);
627	        }
628	
629	        memcpy(&elements->uuid, &attr_inst->uuid, sizeof(bt_uuid_t));
630	    }
631	    svc_table->start_handle = svc_table->elements[0].handle;
632	    svc_table->end_handle = svc_table->elements[svc_table->element_size - 1].handle;
633	
634	    bt_status_t status = bt_sal_gatt_server_add_elements(svc_table->elements, svc_table->element_size);
635	    if (status != BT_STATUS_SUCCESS) {
636	        service_table_delete(svc_table);
637	        return status;
638	    }
639	
640	    bt_list_add_tail(service->tables, svc_table);
641	    return BT_STATUS_SUCCESS;
642	}
