252	static void gatts_process_message(void* data)
253	{
254	    gatts_service_t* service;
255	    gatts_msg_t* msg = (gatts_msg_t*)data;
256	
257	    pthread_mutex_lock(&g_gatts_manager.device_lock);
258	    if (!g_gatts_manager.started)
259	        goto end;
260	
261	    switch (msg->event) {
262	    case GATTS_EVENT_ATTR_TABLE_ADDED: {
263	        service = find_gatts_service_by_id(msg->param.added.element_id);
264	        if (service) {
265	            GATT_CBACK(service->callbacks, on_attr_table_added, service, msg->param.added.status, msg->param.added.element_id ^ service->srv_id);
266	        }
267	    } break;
268	    case GATTS_EVENT_ATTR_TABLE_REMOVED: {
269	        service = find_gatts_service_by_id(msg->param.removed.element_id);
270	        if (service) {
271	            service_table_t* svc_table = find_service_table_by_id(service, msg->param.removed.element_id);
272	            if (svc_table) {
273	                bt_list_remove(service->tables, svc_table);
274	            }
275	            GATT_CBACK(service->callbacks, on_attr_table_removed, service, msg->param.removed.status, msg->param.removed.element_id ^ service->srv_id);
276	        }
277	    } break;
278	    case GATTS_EVENT_CONNECT_CHANGE: {
279	        profile_connection_state_t connect_state = msg->param.connect_change.state;
280	        BT_ADDR_LOG("GATTS-CONNECTION-STATE-EVENT from:%s, state:%d", &msg->param.connect_change.addr, connect_state);
281	        if (connect_state == PROFILE_STATE_CONNECTED) {
282	            GATTS_CALLBACK_FOREACH(g_gatts_manager.services, gatts_service_t, on_connected, &msg->param.connect_change.addr);
283	        } else if (connect_state == PROFILE_STATE_DISCONNECTED) {
284	            GATTS_CALLBACK_FOREACH(g_gatts_manager.services, gatts_service_t, on_disconnected, &msg->param.connect_change.addr);
285	        }
286	    } break;
287	    case GATTS_EVENT_READ_REQUEST: {
288	        service = find_gatts_service_by_id(msg->param.read.element_id);
289	        if (!service)
290	            break;
291	
292	        gatt_element_t* element = find_service_element_by_id(service, msg->param.read.element_id);
293	        if (!element)
294	            break;
295	
296	        if (element->rsp_type == ATTR_AUTO_RSP || element->rsp_type == ATTR_AUTO_RSP_CCC_READ) {
297	            bt_sal_gatt_server_send_response(PRIMARY_ADAPTER, &msg->param.read.addr, msg->param.read.request_id, element->attr_data, element->attr_length);
298	        } else if (element->read_cb) {
299	            element->read_cb(service, &msg->param.read.addr, msg->param.read.element_id ^ service->srv_id, msg->param.read.request_id);
300	        }
301	    } break;
302	    case GATTS_EVENT_WRITE_REQUEST: {
303	        service = find_gatts_service_by_id(msg->param.write.element_id);
304	        if (!service)
305	            break;
306	
307	        gatt_element_t* element = find_service_element_by_id(service, msg->param.write.element_id);
308	        if (!element)
309	            break;
310	
311	        bt_sal_gatt_server_send_response(PRIMARY_ADAPTER, &msg->param.write.addr, msg->param.write.request_id, NULL, 0);
312	        if (element->rsp_type == ATTR_AUTO_RSP) {
313	            if (element->attr_data) {
314	                msg->param.write.length = MIN(element->attr_length, msg->param.write.length);
315	                memcpy(element->attr_data, msg->param.write.value, msg->param.write.length);
316	            }
317	        } else if (element->write_cb) {
318	            element->write_cb(service, &msg->param.write.addr, msg->param.write.element_id ^ service->srv_id, msg->param.write.value,
319	                msg->param.write.length, msg->param.write.offset);
320	        }
321	    } break;
322	    case GATTS_EVENT_MTU_CHANGE:
323	        GATTS_CALLBACK_FOREACH(g_gatts_manager.services, gatts_service_t, on_mtu_changed, &msg->param.mtu_change.addr, msg->param.mtu_change.mtu);
324	        break;
325	    case GATTS_EVENT_CHANGE_SEND: {
326	        service = find_gatts_service_by_id(msg->param.change_send.element_id);
327	        if (service) {
328	            GATT_CBACK(service->callbacks, on_notify_complete, service, &msg->param.change_send.addr, msg->param.change_send.status,
329	                msg->param.change_send.element_id ^ service->srv_id);
330	        }
