717	    gatts_service_t* service = req->srv_handle;
718	#if defined(CONFIG_BLUETOOTH_STACK_LE_ZBLUE)
719	    gatt_element_t* element;
720	#endif
721	
722	    if (!g_gatts_manager.started)
723	        goto out;
724	
725	    bt_list_node_t* node;
726	    for (node = bt_list_head(g_gatts_manager.services); node != NULL;
727	         node = bt_list_next(g_gatts_manager.services, node)) {
728	        if (bt_list_node(node) == service)
729	            break;
730	    }
731	
732	    if (!node)
733	        goto out;
734	
735	#if defined(CONFIG_BLUETOOTH_STACK_LE_ZBLUE)
736	    element = find_service_element_by_id(service, req->attr_handle + service->srv_id);
737	    if (!element) {
738	        BT_LOGE("%s element null", __func__);
739	        goto out;
740	    }
741	
742	    bt_sal_gatt_server_send_notification(PRIMARY_ADAPTER, &req->peer_addr, element,
743	        req->payload, req->length);
744	#else
745	    bt_sal_gatt_server_send_notification(PRIMARY_ADAPTER, &req->peer_addr,
746	        req->attr_handle + service->srv_id, req->payload, req->length);
747	#endif
748	
749	out:
750	    free(req);
751	}
