 34	BT_DEBUG_MKTIMEVAL_S(service_message_callback);
 35	#define DEFERRED_MSG_TIMEOUT (100) /**< 100ms */
 36	#define DEFFERED_MSG_MAX (50)
 37	
 38	typedef struct {
 39	    struct list_node node;
 40	    union {
 41	        service_func_t func;
 42	        service_init_t init;
 43	        service_func_t cleanup;
 44	    };
 45	    void* msg;
 46	} internel_msg_t;
 47	
 48	typedef struct {
 49	    service_func_t func;
 50	    void* data;
 51	    uv_sem_t signal;
 52	} signal_msg_t;
 53	
 54	static void set_stop(void* data);
 55	
 56	static void set_ready(void* data)
 57	{
 58	    service_loop_t* loop = data;
 59	    struct list_node* node;
 60	    struct list_node* tmp;
 61	    internel_msg_t* imsg;
 62	    int ret;
 63	
 64	    loop->is_running = 1;
 65	    uv_sem_init(&loop->exited, 0);
 66	
 67	    list_for_every_safe(&loop->init_queue, node, tmp)
 68	    {
 69	        imsg = (internel_msg_t*)node;
 70	        ret = imsg->init(NULL);
 71	        list_delete(node);
 72	        free(imsg);
 73	        if (ret != 0) {
 74	            BT_LOGE("%s init process fail: %d", __func__, ret);
 75	            set_stop(data);
 76	            return;
 77	        }
 78	    }
 79	
 80	    if (uv_thread_self() == loop->thread)
 81	        uv_sem_post(&loop->ready);
 82	
 83	    BT_LOGD("set_ready");
 84	}
 85	
 86	static void set_stop(void* data)
 87	{
 88	    service_loop_t* loop = data;
 89	
 90	    loop->is_running = 0;
 91	    uv_close((uv_handle_t*)&loop->async, NULL);
 92	    uv_stop(loop->handle);
 93	    BT_LOGD("set_stopped");
 94	}
 95	
 96	static void service_sync_callback(void* data)
 97	{
 98	    signal_msg_t* msg = (signal_msg_t*)data;
 99	
100	    msg->func(msg->data);
101	    uv_sem_post(&msg->signal);
102	}
103	
104	static void service_message_callback(uv_async_t* handle)
105	{
106	    uv_loop_t* uvloop = handle->loop;
107	    service_loop_t* loop = uvloop->data;
108	    internel_msg_t* imsg;
109	
110	    BT_DEBUG_ENTER_TIME_SECTION(service_message_callback);
111	
112	    for (;;) {
113	        uv_mutex_lock(&loop->msg_lock);
114	        imsg = (internel_msg_t*)list_remove_head(&loop->msg_queue);
115	        uv_mutex_unlock(&loop->msg_lock);
116	        if (!imsg) {
117	            BT_DEBUG_EXIT_TIME_SECTION(service_message_callback);
118	            return;
119	        }
120	
121	        imsg->func(imsg->msg);
122	        free(imsg);
123	    }
124	}
125	
126	static void service_schedule_loop(void* data)
127	{
128	    service_loop_t* loop = data;
129	
130	    int ret = uv_async_init(loop->handle, &loop->async, service_message_callback);
131	    if (ret != 0) {
132	        BT_LOGE("%s async error: %d", __func__, ret);
133	        return;
134	    }
135	
136	    BT_LOGD("%s:%p, async:%p", __func__, loop->handle, &loop->async);
137	    do_in_service_loop(set_ready, loop);
138	    uv_run(loop->handle, UV_RUN_DEFAULT);
139	    loop->is_running = 0;
140	    (void)uv_loop_close(loop->handle);
141	
142	    BT_LOGD("%s %s quit", loop->name, __func__);
143	    uv_sem_post(&loop->exited);
144	}
