154	static int uv_events(int events)
155	{
156	    int pevents = 0;
157	
158	    if (events & POLL_READABLE)
159	        pevents |= UV_READABLE;
160	    if (events & POLL_WRITABLE)
161	        pevents |= UV_WRITABLE;
162	    if (events & POLL_DISCONNECT)
163	        pevents |= UV_DISCONNECT;
164	
165	    return pevents;
166	}
167	
168	static void service_poll_cb(uv_poll_t* handle, int status, int events)
169	{
170	    service_poll_t* poll = (service_poll_t*)handle;
171	    int revents = 0;
172	
173	    if (poll->callback) {
174	        if (status != 0)
175	            revents |= POLL_ERROR;
176	        if (events & UV_READABLE)
177	            revents |= POLL_READABLE;
178	        if (events & UV_WRITABLE)
179	            revents |= POLL_WRITABLE;
180	        if (events & UV_DISCONNECT)
181	            revents |= POLL_DISCONNECT;
182	        poll->callback(poll, revents, poll->userdata);
183	    }
184	}
185	
186	static void handle_close_cb(uv_handle_t* handle)
187	{
188	    if (handle->data)
189	        free(handle->data);
190	}
191	
192	int service_loop_init(void)
193	{
194	    uv_loop_t* uvloop;
195	    service_loop_t* loop;
196	    int ret;
197	
198	    uvloop = get_service_uv_loop();
199	    if (uvloop->data != NULL)
200	        return -1;
201	
202	    loop = calloc(1, sizeof(service_loop_t));
203	    if (loop == NULL) {
204	        ret = -ENOMEM;
205	        goto fail;
206	    }
207	
208	    loop->handle = uvloop;
209	    loop->handle->data = loop;
210	    loop->is_running = 0;
211	    ret = uv_mutex_init(&loop->msg_lock);
212	    if (ret != 0) {
213	        BT_LOGE("%s mutex error: %d", __func__, ret);
214	        goto fail;
215	    }
216	
217	    list_initialize(&loop->msg_queue);
218	    list_initialize(&loop->init_queue);
219	    list_initialize(&loop->deferred_queue);
220	
221	    return 0;
222	
223	fail:
224	    (void)uv_loop_close(uvloop);
225	    free(loop);
226	    return ret;
227	}
228	
229	int service_loop_run(bool start_thread, char* name)
230	{
231	    uv_loop_t* handle = get_service_uv_loop();
232	    service_loop_t* loop = handle->data;
233	
234	    if (start_thread) {
235	        int ret = uv_sem_init(&loop->ready, 0);
236	        if (ret != 0) {
237	            BT_LOGE("%s sem init error: %d", __func__, ret);
238	            return ret;
239	        }
240	
241	        uv_thread_options_t options = {
242	            UV_THREAD_HAS_STACK_SIZE | UV_THREAD_HAS_PRIORITY,
243	            CONFIG_BLUETOOTH_SERVICE_LOOP_THREAD_STACK_SIZE,
244	            CONFIG_BLUETOOTH_SERVICE_LOOP_THREAD_PRIORITY
245	        };
246	        ret = uv_thread_create_ex(&loop->thread, &options, service_schedule_loop, loop);
247	        if (ret != 0) {
248	            BT_LOGE("service loop thread create :%d", ret);
249	            return ret;
250	        }
251	
252	        if (name != NULL && strlen(name) > 0)
253	            snprintf(loop->name, sizeof(loop->name), "%s_%d", name, getpid());
254	        else
255	            snprintf(loop->name, sizeof(loop->name), "loop_%d", getpid());
256	        pthread_setname_np(loop->thread, loop->name);
257	        uv_sem_wait(&loop->ready);
258	        uv_sem_destroy(&loop->ready);
259	        BT_LOGD("%s loop running now !!!", loop->name);
260	    } else {
261	        pthread_setschedprio(loop->thread, CONFIG_BLUETOOTH_SERVICE_LOOP_THREAD_PRIORITY);
262	
263	        BT_LOGD("service loop running now !!!");
264	        service_schedule_loop(loop);
265	    }
266	
267	    return 0;
268	}
269	
270	void service_loop_exit(void)
271	{
272	    uv_loop_t* handle = get_service_uv_loop();
273	    service_loop_t* loop = handle->data;
274	    struct list_node* node;
275	    struct list_node* tmp;
276	
277	    if (loop == NULL) {
278	        (void)uv_loop_close(handle);
279	        return;
280	    }
281	
282	    service_loop_cancel_timer(loop->deferred_timer);
283	    loop->deferred_timer = NULL;
284	
285	    if (loop->is_running) {
286	        do_in_service_loop(set_stop, loop);
287	        uv_sem_wait(&loop->exited);
288	        uv_sem_destroy(&loop->exited);
289	    } else {
290	        uv_run(handle, UV_RUN_ONCE);
291	        (void)uv_loop_close(handle);
292	    }
293	
294	    uv_mutex_lock(&loop->msg_lock);
295	    list_for_every_safe(&loop->init_queue, node, tmp)
296	    {
297	        list_delete(node);
298	        free(node);
299	    }
