    56	static void set_ready(void* data)
    57	{
    58	    service_loop_t* loop = data;
    59	    struct list_node* node;
    60	    struct list_node* tmp;
    61	    internel_msg_t* imsg;
    62	    int ret;
    63	
    64	    loop->is_running = 1;
    65	    uv_sem_init(&loop->exited, 0);
    66	
    67	    list_for_every_safe(&loop->init_queue, node, tmp)
    68	    {
    69	        imsg = (internel_msg_t*)node;
    70	        ret = imsg->init(NULL);
    71	        list_delete(node);
    72	        free(imsg);
    73	        if (ret != 0) {
    74	            BT_LOGE("%s init process fail: %d", __func__, ret);
    75	            set_stop(data);
    76	            return;
    77	        }
    78	    }
    79	
    80	    if (uv_thread_self() == loop->thread)
    81	        uv_sem_post(&loop->ready);
    82	
    83	    BT_LOGD("set_ready");
    84	}
