   104	static void service_message_callback(uv_async_t* handle)
   105	{
   106	    uv_loop_t* uvloop = handle->loop;
   107	    service_loop_t* loop = uvloop->data;
   108	    internel_msg_t* imsg;
   109	
   110	    BT_DEBUG_ENTER_TIME_SECTION(service_message_callback);
   111	
   112	    for (;;) {
   113	        uv_mutex_lock(&loop->msg_lock);
   114	        imsg = (internel_msg_t*)list_remove_head(&loop->msg_queue);
   115	        uv_mutex_unlock(&loop->msg_lock);
   116	        if (!imsg) {
   117	            BT_DEBUG_EXIT_TIME_SECTION(service_message_callback);
   118	            return;
   119	        }
   120	
   121	        imsg->func(imsg->msg);
   122	        free(imsg);
   123	    }
   124	}
