   126	static void service_schedule_loop(void* data)
   127	{
   128	    service_loop_t* loop = data;
   129	
   130	    int ret = uv_async_init(loop->handle, &loop->async, service_message_callback);
   131	    if (ret != 0) {
   132	        BT_LOGE("%s async error: %d", __func__, ret);
   133	        return;
   134	    }
   135	
   136	    BT_LOGD("%s:%p, async:%p", __func__, loop->handle, &loop->async);
   137	    do_in_service_loop(set_ready, loop);
   138	    uv_run(loop->handle, UV_RUN_DEFAULT);
   139	    loop->is_running = 0;
   140	    (void)uv_loop_close(loop->handle);
   141	
   142	    BT_LOGD("%s %s quit", loop->name, __func__);
   143	    uv_sem_post(&loop->exited);
   144	}
