   192	int service_loop_init(void)
   193	{
   194	    uv_loop_t* uvloop;
   195	    service_loop_t* loop;
   196	    int ret;
   197	
   198	    uvloop = get_service_uv_loop();
   199	    if (uvloop->data != NULL)
   200	        return -1;
   201	
   202	    loop = calloc(1, sizeof(service_loop_t));
   203	    if (loop == NULL) {
   204	        ret = -ENOMEM;
   205	        goto fail;
   206	    }
   207	
   208	    loop->handle = uvloop;
   209	    loop->handle->data = loop;
   210	    loop->is_running = 0;
   211	    ret = uv_mutex_init(&loop->msg_lock);
   212	    if (ret != 0) {
   213	        BT_LOGE("%s mutex error: %d", __func__, ret);
   214	        goto fail;
   215	    }
   216	
   217	    list_initialize(&loop->msg_queue);
   218	    list_initialize(&loop->init_queue);
   219	    list_initialize(&loop->deferred_queue);
   220	
   221	    return 0;
   222	
   223	fail:
   224	    (void)uv_loop_close(uvloop);
   225	    free(loop);
   226	    return ret;
   227	}
