   298	        } else if (element->read_cb) {
   299	            element->read_cb(service, &msg->param.read.addr, msg->param.read.element_id ^ service->srv_id, msg->param.read.request_id);
   300	        }
   301	    } break;
   302	    case GATTS_EVENT_WRITE_REQUEST: {
