   311	        bt_sal_gatt_server_send_response(PRIMARY_ADAPTER, &msg->param.write.addr, msg->param.write.request_id, NULL, 0);
   312	        if (element->rsp_type == ATTR_AUTO_RSP) {
   313	            if (element->attr_data) {
   314	                msg->param.write.length = MIN(element->attr_length, msg->param.write.length);
   315	                memcpy(element->attr_data, msg->param.write.value, msg->param.write.length);
