   329	                msg->param.change_send.element_id ^ service->srv_id);
   330	        }
   331	    } break;
   332	    case GATTS_EVENT_PHY_READ: {
   333	        gatts_op_t* operation = gatts_pendops_execute_out(&g_gatts_manager, GATTS_REQ_READ_PHY);
   334	        if (operation) {
