   342	            GATTS_CALLBACK_FOREACH(g_gatts_manager.services, gatts_service_t, on_phy_updated, &msg->param.phy.addr, msg->param.phy.status,
   343	                msg->param.phy.tx_phy, msg->param.phy.rx_phy);
