   739	        goto out;
   740	    }
   741	
   742	    bt_sal_gatt_server_send_notification(PRIMARY_ADAPTER, &req->peer_addr, element,
   743	        req->payload, req->length);
   744	#else
   745	    bt_sal_gatt_server_send_notification(PRIMARY_ADAPTER, &req->peer_addr,
   746	        req->attr_handle + service->srv_id, req->payload, req->length);
   747	#endif
   748	
   749	out:
   750	    free(req);
   751	}
