   368	static bt_status_t gatts_send_message(gatts_msg_t* msg)
   369	{
   370	    assert(msg);
   371	
   372	    do_in_service_loop(gatts_process_message, msg);
   373	
   374	    return BT_STATUS_SUCCESS;
   375	}
