   753	static bt_status_t if_gatts_notify(void* srv_handle, bt_address_t* addr, uint16_t attr_handle, uint8_t* value, uint16_t length)
   754	{
   755	    gatts_notify_req_t* req;
   756	
   757	    if (!value)
   758	        return BT_STATUS_PARM_INVALID;
   759	
   760	    req = malloc(sizeof(*req) + length);
   761	    if (!req)
   762	        return BT_STATUS_NOMEM;
   763	
   764	    req->srv_handle = srv_handle;
   765	    memcpy(&req->peer_addr, addr, sizeof(req->peer_addr));
   766	    req->attr_handle = attr_handle;
   767	    req->length = length;
   768	    memcpy(req->payload, value, length);
   769	
   770	    do_in_service_loop(gatts_notify_in_service_loop, req);
   771	    return BT_STATUS_SUCCESS;
   772	}
