   256	/****************************************************************************
   257	 * Name: arg_string
   258	 ****************************************************************************/
   259	
   260	static int arg_string(FAR char **arg, FAR char **value)
   261	{
   262	  FAR char *ptr = *arg;
   263	
   264	  if (ptr[2] == '\0')
   265	    {
   266	      *value = arg[1];
   267	      return 2;
   268	    }
   269	  else
   270	    {
   271	      *value = &ptr[2];
   272	      return 1;
   273	    }
   274	}
   275	
   276	/****************************************************************************
   277	 * Name: arg_decimal
   278	 ****************************************************************************/
   279	
   280	static int arg_decimal(FAR char **arg, FAR long *value)
   281	{
   282	  FAR char *string;
   283	  int ret;
   284	
   285	  ret = arg_string(arg, &string);
   286	  *value = strtol(string, NULL, 10);
   287	  return ret;
   288	}
   289	
   290	/****************************************************************************
   291	 * Name: parse_args
   292	 ****************************************************************************/
   293	
   294	static void parse_args(FAR struct pwm_state_s *pwm, int argc,
   295	                       FAR char **argv)
   296	{
   297	  FAR char *ptr;
   298	  FAR char *str;
   299	  long value;
   300	  int index;
   301	  int nargs;
   302	#ifdef CONFIG_PWM_MULTICHAN
   303	  int nchannels = 0;
   304	  int nduties   = 0;
   305	#endif
   306	
   307	  for (index = 1; index < argc; )
   308	    {
   309	      ptr = argv[index];
   310	      if (ptr[0] != '-')
   311	        {
   312	          printf("Invalid options format: %s\n", ptr);
   313	          exit(0);
   314	        }
   315	
   316	      switch (ptr[1])
   317	        {
   318	          case 'f':
   319	            nargs = arg_decimal(&argv[index], &value);
   320	            if (value < 1)
   321	              {
   322	                printf("Frequency out of range: %ld\n", value);
   323	                exit(1);
   324	              }
   325	
   326	            pwm->freq = (uint32_t)value;
   327	            index += nargs;
   328	            break;
   329	
   330	#ifdef CONFIG_PWM_MULTICHAN
   331	          case 'c':
   332	            nargs = arg_decimal(&argv[index], &value);
   333	            if (value < -1 || value > CONFIG_PWM_NCHANNELS)
   334	              {
   335	                printf("Channel out of range: %ld\n", value);
   336	                exit(1);
   337	              }
   338	
   339	            if (nchannels < CONFIG_PWM_NCHANNELS)
   340	              {
   341	                nchannels++;
   342	              }
   343	            else
   344	              {
   345	                memmove(pwm->channels, pwm->channels + 1,
   346	                        CONFIG_PWM_NCHANNELS - 1);
   347	              }
   348	
   349	            pwm->channels[nchannels - 1] = (int8_t)value;
   350	            index += nargs;
   351	            break;
   352	#endif
   353	
   354	          case 'd':
   355	            nargs = arg_decimal(&argv[index], &value);
   356	            if (value < 0 || value > 100)
   357	              {
   358	                printf("Duty out of range: %ld\n", value);
   359	                exit(1);
   360	              }
   361	
   362	#ifdef CONFIG_PWM_MULTICHAN
   363	            if (nduties < CONFIG_PWM_NCHANNELS)
   364	              {
   365	                nduties++;
   366	              }
   367	            else
   368	              {
   369	                memmove(pwm->duties, pwm->duties + 1,
   370	                        CONFIG_PWM_NCHANNELS - 1);
   371	              }
   372	
   373	            pwm->duties[nduties - 1] = (uint8_t)value;
   374	#else
   375	            pwm->duty = (uint8_t)value;
   376	#endif
   377	            index += nargs;
   378	            break;
   379	
   380	#ifdef CONFIG_PWM_PULSECOUNT
   381	          case 'n':
   382	            nargs = arg_decimal(&argv[index], &value);
   383	            if (value < 0)
   384	              {
   385	                printf("Count must be non-negative: %ld\n", value);
   386	                exit(1);
   387	              }
   388	
   389	            pwm->count = (uint32_t)value;
   390	            index += nargs;
   391	            break;
   392	#endif
   393	
   394	          case 'p':
   395	            nargs = arg_string(&argv[index], &str);
   396	            pwm_devpath(pwm, str);
   397	            index += nargs;
   398	            break;
   399	
   400	          case 't':
   401	            nargs = arg_decimal(&argv[index], &value);
   402	            if (value < 1 || value > INT_MAX)
   403	              {
   404	                printf("Duration out of range: %ld\n", value);
   405	                exit(1);
   406	              }
   407	
   408	            pwm->duration = (int)value;
   409	            index += nargs;
   410	            break;
   411	
   412	          case 'h':
   413	            pwm_help(pwm);
   414	            exit(0);
   415	
   416	          default:
   417	            printf("Unsupported option: %s\n", ptr);
   418	            pwm_help(pwm);
   419	            exit(1);
   420	        }
