   313	          exit(0);
   314	        }
   315	
   316	      switch (ptr[1])
   317	        {
   318	          case 'f':
   319	            nargs = arg_decimal(&argv[index], &value);
   320	            if (value < 1)
   321	              {
   322	                printf("Frequency out of range: %ld\n", value);
   323	                exit(1);
   324	              }
   325	
   326	            pwm->freq = (uint32_t)value;
   327	            index += nargs;
   328	            break;
   329	
   330	#ifdef CONFIG_PWM_MULTICHAN
   331	          case 'c':
   332	            nargs = arg_decimal(&argv[index], &value);
   333	            if (value < -1 || value > CONFIG_PWM_NCHANNELS)
   334	              {
   335	                printf("Channel out of range: %ld\n", value);
   336	                exit(1);
   337	              }
   338	
   339	            if (nchannels < CONFIG_PWM_NCHANNELS)
   340	              {
