   347	              }
   348	
   349	            pwm->channels[nchannels - 1] = (int8_t)value;
   350	            index += nargs;
   351	            break;
   352	#endif
   353	
   354	          case 'd':
   355	            nargs = arg_decimal(&argv[index], &value);
   356	            if (value < 0 || value > 100)
   357	              {
   358	                printf("Duty out of range: %ld\n", value);
   359	                exit(1);
   360	              }
   361	
   362	#ifdef CONFIG_PWM_MULTICHAN
   363	            if (nduties < CONFIG_PWM_NCHANNELS)
