static void probe_print_gesture_stats(void)
{
  uint32_t enqueued;
  uint32_t full;
  uint32_t acked;
  uint32_t retransmitted;
  uint32_t dropped;
  uint32_t tx_status_nonzero;

  pthread_mutex_lock(&g_state_lock);
  enqueued = g_gesture_enqueued;
  full = g_gesture_queue_full;
