   891	    }
   892	  else
   893	    {
   894	      i2c_errors++;
   895	    }
   896	
   897	  if (fifo_started)
   898	    {
   899	      cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   900	                                        PROBE_IMU_FIFO_CTRL5,
   901	                                        PROBE_IMU_FIFO_BYPASS);
   902	      if (cleanup_ret != 0 && restore_status == 0)
   903	        {
   904	          restore_status = cleanup_ret;
   905	        }
   906	    }
   907	
   908	restore:
   909	  /* Restore sensors, FIFO configuration/mode, pulse mode, then INT1. */
   910	
   911	  for (i = 7; i < 10; i++)
   912	    {
   913	      if (saved_valid[i])
   914	        {
   915	          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   916	                                            registers[i], saved[i]);
   917	          if (cleanup_ret != 0 && restore_status == 0)
   918	            {
   919	              restore_status = cleanup_ret;
   920	            }
   921	        }
   922	    }
   923	
   924	  for (i = 0; i < 5; i++)
   925	    {
   926	      if (saved_valid[i])
   927	        {
   928	          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   929	                                            registers[i], saved[i]);
   930	          if (cleanup_ret != 0 && restore_status == 0)
   931	            {
   932	              restore_status = cleanup_ret;
   933	            }
   934	        }
   935	    }
   936	
   937	  for (i = 5; i < 7; i++)
   938	    {
   939	      if (saved_valid[i])
   940	        {
   941	          cleanup_ret = probe_imu_write_reg(fd, PROBE_IMU_ADDR,
   942	                                            registers[i], saved[i]);
   943	          if (cleanup_ret != 0 && restore_status == 0)
   944	            {
   945	              restore_status = cleanup_ret;
   946	            }
   947	        }
   948	    }
   949	
   950	  if (semaphore_initialized)
   951	    {
   952	      sem_destroy(&g_imu_drdy_sem);
   953	    }
   954	
   955	  fifo_irq_count = __atomic_load_n(&g_imu_drdy_irq_count,
   956	                                    __ATOMIC_RELAXED);
   957	  if (start_us != 0 && clock_gettime(CLOCK_MONOTONIC, &now) == 0)
   958	    {
   959	      end_us = probe_timespec_us(&now);
   960	    }
   961	
   962	  printf("openvela_ble_probe: IMU FIFO summary duration_ms=%u"
   963	         " elapsed_ms=%llu"
   964	         " fifo_irq_count=%lu fifo_wake_count=%lu fifo_words_read=%lu"
   965	         " gyro_samples=%lu accel_samples=%lu"
   966	         " paired_six_axis_samples=%lu startup_discarded_words=%lu"
   967	         " fifo_watermark_events=%lu fifo_overrun=%lu fifo_smart_full=%lu"
   968	         " max_fifo_depth_words=%lu unpaired_or_unexpected_frames=%lu"
   969	         " i2c_errors=%lu timeouts=%lu end_depth_words=%u\n",
   970	         BLE_PROBE_IMU_DRDY_TEST_DURATION_MS,
   971	         (unsigned long long)(start_us == 0 || end_us < start_us ? 0 :
   972	                              (end_us - start_us) / 1000),
   973	         (unsigned long)fifo_irq_count, (unsigned long)fifo_wake_count,
   974	         (unsigned long)fifo_words_read, (unsigned long)gyro_samples,
   975	         (unsigned long)accel_samples, (unsigned long)paired_samples,
   976	         (unsigned long)startup_discarded_words,
   977	         (unsigned long)fifo_watermark_events,
   978	         (unsigned long)fifo_overrun, (unsigned long)fifo_smart_full,
   979	         (unsigned long)max_fifo_depth_words,
   980	         (unsigned long)unexpected_frames, (unsigned long)i2c_errors,
   981	         (unsigned long)timeouts, end_depth_words);
   982	  printf("openvela_ble_probe: IMU FIFO registers restored status=%d\n",
   983	         restore_status);
   984	  close(fd);
   985	  return NULL;
   986	}
