  1027	static int probe_monotonic_ms(uint64_t *now_ms)
  1028	{
  1029	  struct timespec now;
  1030	
  1031	  if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
  1032	    {
  1033	      return -1;
  1034	    }
  1035	
  1036	  *now_ms = (uint64_t)now.tv_sec * 1000u +
  1037	            (uint64_t)now.tv_nsec / 1000000u;
  1038	  return 0;
  1039	}
